#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""LightPrism · OpenI / V100 单文件训练与思路验证脚本

一次上传、直接运行::

    python train_openi.py                     # 完整实验（默认 demo 档，V100 数分钟）
    python train_openi.py --smoke            # 先验环境：2 步前向/反向 + 2 条生成
    python train_openi.py --self-check       # 纯标准库自检（不需要 torch）

它回答的不是「loss 降没降」，而是方案书 docs/探针实验设计.md 的四条判据：

1. 决策 token 在**共享表征**里是否可读（线性探针 vs 外挂分类器 A 组）；
2. 加入决策/验证 token 是否**挤占生成能力**（C 组 vs 去掉控制 token 的 B 组）；
3. 模型自己（**不加外部状态机约束**）能否吐出合法序列，结构合法率 ≥ 95%；
4. 决策密度 ≤ 2% 且生成速度相对 B 组下降 ≤ 15%。

诚实边界（必须先读，否则会把机制验证误读成能力证明）
------------------------------------------------------
* 仓库现有 363 条 SFT 样本的 ``steps[].decisions`` **全为空**、
  ``validation`` **全是 PASS**。也就是说：真实决策监督信号为 0，
  8 个 ``<V:ERR=...>`` 类验证 token 一个正样本都没有。
* 因此本脚本默认 ``--decision-policy real``：只从 ``decision`` 类 50 条样本的
  **真实答案**里取 ``<D:EDIT=...>``，其余样本不注入决策 token；6 个决策点无样本，
  报告里逐点标 ``no_samples``，不进宏平均，也不假装覆盖。
* ``--decision-policy rule`` 会派生 7 个决策点的标签，按样本内容确定性轮转、
  每条只注入 2 个（全注入会让密度突破 2% 硬上限）。标签是**规则派生**的合成标签，
  只允许验证机制（命名空间隔离、探针可读性、密度），
  ``evidence_level`` 会被锁成 ``mechanism_only``，verdict 不会报 pass。
* ``--shuffle-control``（默认开）把决策标签在同决策点内打乱后重训一个同规模模型。
  若打乱组探针准确率也高，说明特征里带着标签，本次结论作废——这是反向判别力哨兵。
  探针主特征取**决策 token 前一位置（pos-1）**；取自身位置等于把答案直接写进输入
  （v1 实测 C 组与打乱组探针都恰好 1.000），脚本额外把自身位置探针列为泄漏对照。
* 约束解码的结构合法率是**外部状态机强制**出来的，必然接近 100%，属于假绿。
  判据 3 只用**无约束**贪心解码的裸结构合法率；约束版只作对照列示。
* 真正的「一次通过率」要跑 ``light ai check --json --run``，OpenI 环境没有光明解释器。
  本脚本对 300 条 JSON 任务用「生成 CODE 段 json.loads 成功 / 与标准答案相等」
  作本地代理，光明代码类 63 条记 unknown，不并入通过率。

环境与口径
----------
* V100 (SM70) 没有 bf16 Tensor Core，**按 compute capability 强制 fp16 + GradScaler**：
  torch 2.10 在 V100 上 ``is_bf16_supported()`` 会返回 True（软件可跑、无加速、
  尾数精度还低于 fp16），不能拿它当判据。Ampere+ 自动 bf16，CPU fp32。
  torch 1.13 / 2.x / 3.x 的 amp API 都做了兼容探测。
* 词表 = 仓库 ``data/vocab_4096.json``（2900 条实词，控制 token 连续区间
  ``[2868, 2900)``）；训练侧额外加 PAD=2900 / UNK=2901 两个**非控制**特殊 id，
  控制区间的「按 id 判型」不变。
* 模型与 ``src/lightprism/model.py`` 同构：pre-norm RMSNorm + QK-Norm + RoPE +
  SwiGLU + tied embedding。内联实现是为了单文件可上传，不依赖 pip install。
* 数据、词表以 zlib+base64 内嵌在文件末尾，SHA-256 会在 config.json 里留痕；
  也可 ``--data-dir DIR`` 指向外部真实数据覆盖。

输出（默认 ``./lightprism_out/``）::

    config.json  train_log.jsonl  metrics.json  report.md
    generated_samples.jsonl  checkpoints/*.pt

OpenI 启智：脚本不强制依赖 c2net。若训练任务里需要把结果回传，加 ``--c2net``
（读取 ``prepare()`` 的 output_path）与 ``--c2net-upload``（结束时 upload_output）。

v2 修复（2026-11-12，依据 OpenI Tesla V100S 首轮实测输出）
----------------------------------------------------------
1. **探针特征改取 pos-1**，并新增「自身位置」泄漏对照。v1 的 C 组 / 打乱组 /
   A 组探针 1.000 全部作废：那个 1.0 是抄输入里的决策 token，不是表征学到了决策。
2. UNK 率改为按传入序列统计 ``unk_id``，不再读 ``Vocab.unk_count`` 全局累积
   计数器（v1 会随构建次数翻倍：本机 77 / OpenI 154）。
3. V100 强制 fp16；判据 ②③ 加 ≥30 评估样本门槛；``--eval-gen-samples`` 默认 52。
4. 日志里 ``float(loss)`` 改 ``float(loss.detach())``，消掉 requires_grad 警告。

v3 修复（2026-11-12，依据 reports/探针实验_v2_评审_2026-11-12.md）
--------------------------------------------------------------------
v2 的 ``verdict=fail`` 经复核是**测量无效**，不是方案被证伪：探针只覆盖 1/7 个
决策点、评估样本 7 条且与 train 模板 100% 重合、判据 ③ 分母排除了截断生成、
判据 ② 的 pass 只差 1 条样本。四条判据无一具备判别力，按 §6 调参是错的方向。

1. **补门禁（P0）**：决策点覆盖 < 7 / 探针 test < 30 / train-test 模板重合 /
   验证 token 无 ERR 类正样本，任一命中 → 四条判据逐条记 ``unknown``，
   整体 verdict 降为 ``incomplete``（**不再报 fail**）。fail 的强度超过证据强度。
2. **按模板簇分组切分（P0）**：``stratified_split`` 增加 ``--group-split``，
   同一 ``category+归一化 task 模板`` 的变体不跨 train/val/test。v2 里
   decision 类 6 条 test 的 task 文本在 train 里一字不差出现过，A 组 1.000 是记忆。
3. **判据 ③ 全分母（P1）**：截断生成 = 未吐出 ``</CODE>``/``<V:...>`` 的失败输出，
   必须计入分母；``--max-new-tokens`` 默认 160 → 384（覆盖实测 p95=330）。
   ``n_counted``/``n_truncated`` 写进 metrics，不再让分母藏在报告外。
4. **判据 ② 显著性 + 口径拆分（P1）**：JSON 代理与真实一次通过率分成两列；
   C/B 精确匹配差 < 3 条（``--min-decisive-gap``）记 unknown，堵住 8/42 vs 7/42。
5. **判据 ① 可测化（P1）**：``--decision-position`` 支持把决策 token 随机插入
   任务段之后（不再永远紧跟 ``</TASK>``，否则 pos-1 是常数）；报告里显式记录
   「决策 token 前最近控制 token」分布；天花板保护放宽到任一组 ≥0.95 且 n_test<30。
6. **A 组对等对照（P1）**：新增 ``--a-group-rival``，用「冻结主干 + 同位置
   hidden + MLP」跑一个与探针同特征基线的 A'，与 390419 参数的文本分类器并列报。
7. **嵌入几何检查点（P2）**：按方案 §7 阶段一检查点，计算决策 token 嵌入与
   代码 token 嵌入的余弦相似度分布，以及「从未被训练过的决策 token 个数」；
   ``grad_norm_control_rows/grad_norm_text_rows`` 比值摘要写进报告（§8.6）。
8. **产出物对齐 §8（P3）**：训练结束把 ``reports/探针实验_<日期>.{md,json}``
   一并落盘；默认 ``--decision-policy`` 仍为 real，但门禁会如实报 incomplete。

本机只做纯标准库复核（无 GPU）。真训练仍需上传 OpenI/V100 重跑。

v3.1 修复（2026-11-12，依据第二次 OpenI 实测输出）
--------------------------------------------------
用 ``--group-split --decision-position scattered --a-group-rival`` 重跑后，
v2 的诊断被实测坐实：A 组从 1.000 掉到 0.6154（模板零重合，证明满分是背模板）；
C 探针与打乱组同为 0.3846、A'=0.3077，均不显著高于随机（n=13, p=1/3）。
但输出也照出 v3 自身四个测量 bug：

1. **scattered 是空转开关**：初版取 ``task_tail[-k:]``，而本库 363 条 task
   全以「输出 JSON。」结尾，实测 48/48 条决策 token 的前一 token 都是 ``。``
   (id=46) —— 只是把常数从 ``</TASK>`` 换成 ``。``。改为从任务文本**中段随机
   截取**窗口（排除末尾 6 个固定套话 token），pos-1 真正变化。
2. **``describe_prev`` 折叠所有文本 token 为 ``"<text>"``**：导致
   ``feature_is_constant`` 在 scattered 模式下永远为真，哨兵结构上不可能报
   False。改为带真实 token 文本 + id，并按**不同 id 数**判定；且明确区分
   「输入 token 恒定」与「hidden 向量恒定」。
3. **``n_decision_tokens_never_trained`` 误导**：模型是 tied embedding，
   实测一步前后 ``embed.grad`` 非零行数 2902/2902、19 个决策 token 行全部
   有梯度（含 16 个「从未作为输入」的）。改名 ``never_seen_as_input``，
   拆出「曾作为输入」子集的余弦分布，并写明余弦整体升高不能单独证明共存。
4. **门禁措辞与实现不一致**：caveats 说「四条判据无一具备判别力」，但
   ③④ 不依赖决策标签、本就是有效测量（③ 的 0.7115 是这轮最可信数字）。
   改为：门禁只封 ① 与差距不足的 ②；综合结论仍记 incomplete。

修完这四处 verdict **不会翻盘**：1/7 决策点、n=13<30、无 ERR 类验证三项仍在。

v3.2 修复（2026-11-12，依据第三次 OpenI 实测：scattered 与默认两次对照）
----------------------------------------------------------------------
这轮把 v3.1 修出来的两个新问题也照出来了，并顺带发现一个更硬的结论：

1. **``scattered`` 训练/推理不一致，把判据 ③ 打崩**：训练序列在 ``</TASK>``
   后插了任务文本窗口，但 ``generate()`` 的 prompt 仍只到 ``</TASK>``。
   实测同样 C 组：默认 ③=0.9808（51/52），scattered 只有 0.4808（25/52）。
   修复：窗口改由 ``decision_window()`` 从 ``sha256(task+code)`` 确定性派生，
   ``build_ids()`` 与 ``generate()`` 共用同一窗口，推理 prompt 同步补上。
2. **「token 恒定」不等于「特征恒定」**：本机实测 13/13 决策 token 的 pos-1
   都是同一个 ``</TASK>``，但对应 hidden 各维 std 均值 **0.60**、两两 L2 距离
   均值 **11.65**、有效秩 4/13。v3.1 用 token id 种类数当门禁，拦错了对象。
   修复：``feature_is_constant`` 改为按 **hidden 各维 std** 判定；
   token 种类数只作报告，不再参与门禁。
3. **C 探针恰好等于多数类基线**：分组切分后 EDIT test 13 条的类别分布是
   ``{RW:5, FR:5, PATCH:3}``，恒预测多数类就是 5/13 = **0.3846**，而 C 实测
   也是 **0.3846**；默认切分下 C=0.5556，多数类 4/9=0.4444（差 1 条）。
   新增 ``majority_baseline`` 逐点基线与 ``macro_majority_baseline``：
   C ≤ 多数类时判据 ① 记 unknown「等价于恒预测多数类，零信号」，
   而不是去和 A 组做无意义的比较。

几何检查点同时给出更有意义的拆分：真正作为输入出现过的 3 个
``<D:EDIT=*>`` 与文本行余弦只有 **0.10—0.13**（近正交），而 16 个从未作为
输入的反而是 **0.41—0.42**——旧口径的 overall 0.37 是 softmax 共同方向漂移，
不能当作「进入同一语义场」。
"""
