# 这种「擦边通过」没有判别力，宁可记 unknown。
MIN_DECISIVE_SAMPLES = 30
# v3：判据 ② 除样本量外还要看「差距」。v2 里 C=8/42、B=7/42，差 1 条就判 pass，
# 没有任何统计判别力。精确匹配相差少于该条数时记 unknown。
MIN_DECISIVE_GAP = 3
# v3 门禁：探针要覆盖全部 7 个决策点、每个点有足够 test 样本、train/test 模板不重合。
MIN_PROBE_TEST_ROWS = 30
N_DECISION_POINTS = 7
# 判据 ① 天花板：任一组达到该准确率且 test 样本不足时，比较无意义。
CEILING_ACC = 0.95
# 决策 token 归一化模板时抹掉的可变部分（数字序号 / 天干占位符），用于分组切分。
_TEMPLATE_NUM_RE = re.compile(r"\d+")
_TEMPLATE_VAR_RE = re.compile(r"[甲乙丙丁戊己庚辛壬癸]")

PRESETS = {
    # 与 configs/demo-3m.json 同量级；max_seq 放宽到 1024 是为容纳实测最长 662 token 样本
    "demo": dict(dim=192, n_layers=6, n_heads=6, ffn_mult=4.0, max_seq=1024),
    "small": dict(dim=384, n_layers=8, n_heads=8, ffn_mult=4.0, max_seq=1024),
    # 320M 档，V100 16G 需要 --batch-size 4 --seq-len 512
    "300m": dict(dim=1024, n_layers=20, n_heads=16, ffn_mult=4.0, max_seq=1024),
}


# ===========================================================================
# 0. payload / 环境
# ===========================================================================
def _load_payload(args: argparse.Namespace) -> Dict[str, Any]:
    if args.data_dir:
        d = Path(args.data_dir)
        vocab = json.loads((d / "vocab_4096.json").read_text(encoding="utf-8"))
        payload = {
            "vocab": {k: vocab[k] for k in ("schema_version", "kind", "size", "tokens",
                                           "kinds", "control_layout", "counts") if k in vocab},
            "json_tasks": (d / "json_tasks.jsonl").read_text(encoding="utf-8"),
            "code_tasks": (d / "code_tasks.jsonl").read_text(encoding="utf-8"),
            "meta": {"source": "external-data-dir", "dir": str(d.resolve())},
        }
        # err_tasks 可选：不存在则为空字符串，不报错
        err_path = d / "err_tasks.jsonl"
        payload["err_tasks"] = err_path.read_text(encoding="utf-8") if err_path.is_file() else ""
        # T-0494：真实决策快照，与 err_tasks 同样「缺失即空串」，不报错
        dec_path = d / "decisions.jsonl"
        payload["decisions"] = dec_path.read_text(encoding="utf-8") if dec_path.is_file() else ""
    else:
        raw = zlib.decompress(base64.b64decode("".join(_PAYLOAD_B64.split())))
        payload = json.loads(raw.decode("utf-8"))
        # 兼容旧 payload：没有 err_tasks 字段时补空串
        payload.setdefault("err_tasks", "")
        # 兼容旧 payload：缺 decisions 时行为完全不变（不报错、不注入决策样本）
        payload.setdefault("decisions", "")
    payload["meta"] = dict(payload.get("meta") or {})
    for k in ("json_tasks", "code_tasks", "err_tasks", "decisions"):
        payload["meta"][k + "_sha256"] = hashlib.sha256(
            payload[k].encode("utf-8")).hexdigest()
    payload["meta"]["vocab_sha256"] = hashlib.sha256(
        json.dumps(payload["vocab"], ensure_ascii=False, sort_keys=True).encode("utf-8")
    ).hexdigest()
    return payload


def env_report(device) -> Dict[str, Any]:
    import torch
    out: Dict[str, Any] = {
        "python": sys.version.split()[0],
        "torch": torch.__version__,
        "cuda_available": torch.cuda.is_available(),
        "device": str(device),
    }
    if torch.cuda.is_available():
        p = torch.cuda.get_device_properties(device)
        out.update({
            "gpu": p.name,
            "compute_capability": f"{p.major}.{p.minor}",
            "gpu_memory_gb": round(p.total_memory / (1024 ** 3), 2),
            "torch_is_bf16_supported": bool(getattr(torch.cuda, "is_bf16_supported", lambda: False)()),
            "native_bf16_tensorcore": p.major >= 8,
            "cudnn": torch.backends.cudnn.version(),
        })
    return out


def amp_helpers(device, torch, amp_mode: str):
    """返回 (autocast_ctx_factory, scaler, dtype_name)。

    V100/Volta (SM70) 没有 bf16 Tensor Core。实测 torch 2.10+cu128 在
    Tesla V100S 上 ``is_bf16_supported()`` 返回 **True**（bf16 可软件模拟），
    但既拿不到硬件加速、尾数精度还低于 fp16（7 位 vs 10 位）。
    因此按 compute capability 判断：SM < 8.0 一律 fp16 + GradScaler，
    只有 Ampere+ 且 torch 也报告支持时才用 bf16。
    """
    if device.type != "cuda":
        return (lambda: contextlib.nullcontext()), None, "fp32"
    major, minor = torch.cuda.get_device_capability(device)
    native_bf16 = major >= 8
    torch_says = bool(getattr(torch.cuda, "is_bf16_supported", lambda: False)())
    if amp_mode == "off":
        return (lambda: contextlib.nullcontext()), None, "fp32"
    if amp_mode == "auto":
        dtype = torch.bfloat16 if (native_bf16 and torch_says) else torch.float16
        print(f"[amp] SM{major}.{minor} native_bf16_tensorcore={native_bf16}, "
              f"torch.is_bf16_supported={torch_says} -> {dtype} "
              + ("（V100/Volta 强制 fp16，不要被 torch 的 True 骗了）" if not native_bf16 else ""))
    elif amp_mode == "bf16":
        dtype = torch.bfloat16
    elif amp_mode == "fp16":
        dtype = torch.float16
    else:
        raise ValueError(f"未知 --amp {amp_mode}")

    def ctx():
        try:  # torch >= 2.4
            return torch.amp.autocast(device_type="cuda", dtype=dtype)
        except (AttributeError, TypeError):  # torch 1.13 ~ 2.3
            return torch.cuda.amp.autocast(dtype=dtype)

    scaler = None
    if dtype == torch.float16:
        try:
            scaler = torch.amp.GradScaler("cuda", enabled=True)
        except (AttributeError, TypeError):
            scaler = torch.cuda.amp.GradScaler(enabled=True)
    return ctx, scaler, str(dtype).replace("torch.", "")


# ===========================================================================
# 1. 纯标准库层：词表 / 序列 / 切分 / batch
# ===========================================================================
class Vocab:
    """2900 条实词表 + 控制 token 连续区间 + 训练用 PAD/UNK。

    分词用贪心最长匹配；L0 44 字强制一字一 token（词表构建时已保证
    多字 token 不含 L0 字，这里再兜一次，避免任何粘连）。
    """

    def __init__(self, v: Dict[str, Any]) -> None:
        self.tokens: List[str] = list(v["tokens"])
        lay = v["control_layout"]
        self.ctrl_start, self.ctrl_end = int(lay["start"]), int(lay["end"])
        self.structure: Dict[str, int] = {k: int(x) for k, x in lay["structure"].items()}
        self.decisions: Dict[str, int] = {k: int(x) for k, x in lay["decisions"].items()}
        self.validations: Dict[str, int] = {k: int(x) for k, x in lay["validations"].items()}
        self.index: Dict[str, int] = {t: i for i, t in enumerate(self.tokens)}
        self.pad_id = self.ctrl_end
        self.unk_id = self.ctrl_end + 1
        self.vocab_size = self.ctrl_end + 2

        kinds = v.get("kinds") or []
        self.l0_set = {t for t, k in zip(self.tokens, kinds) if k == "l0"}
        self.decision_ids = set(self.decisions.values())
        self.validation_ids = set(self.validations.values())
        self.structure_ids = set(self.structure.values())
        self.control_ids = list(range(self.ctrl_start, self.ctrl_end))

        self.point_options: Dict[str, List[str]] = defaultdict(list)
        self.point_token_ids: Dict[str, List[int]] = defaultdict(list)
        for text, tid in sorted(self.decisions.items(), key=lambda kv: kv[1]):
            m = DECISION_RE.fullmatch(text)
            if not m:
                raise ValueError(f"非法决策 token: {text}")
            self.point_options[m.group(1)].append(m.group(2))
            self.point_token_ids[m.group(1)].append(tid)
        self.points = sorted(self.point_options)
        self.point_option_id: Dict[str, Dict[str, int]] = {
            p: {o: i for i, o in enumerate(opts)} for p, opts in self.point_options.items()
        }
        self.unk_count = 0

        by_first: Dict[str, List[Tuple[str, int]]] = defaultdict(list)
        for i, t in enumerate(self.tokens[:self.ctrl_start]):
            if t and not t.startswith("<"):
                by_first[t[0]].append((t, i))
        for k in by_first:
            by_first[k].sort(key=lambda kv: -len(kv[0]))
        self.by_first = by_first

        # id -> 类型编号，供 torch 侧按 target 分组统计
        self.KIND = {"text": 0, "structure": 1, "decision": 2, "validation": 3,
                     "unk": 4, "pad": 5}
        self.kind_table: List[int] = [self.KIND["text"]] * self.vocab_size
        for i in self.structure_ids:
            self.kind_table[i] = self.KIND["structure"]
        for i in self.decision_ids:
            self.kind_table[i] = self.KIND["decision"]
        for i in self.validation_ids:
            self.kind_table[i] = self.KIND["validation"]
        self.kind_table[self.pad_id] = self.KIND["pad"]
        self.kind_table[self.unk_id] = self.KIND["unk"]

    def kind_of(self, tid: int) -> str:
        if tid == self.pad_id:
            return "pad"
        if tid == self.unk_id:
            return "unk"
        if tid in self.structure_ids:
            return "structure"
        if tid in self.decision_ids:
            return "decision"
        if tid in self.validation_ids:
            return "validation"
        return "text"

    def ctrl_id(self, text: str) -> int:
        for table in (self.structure, self.decisions, self.validations):
            if text in table:
                return table[text]
        raise ValueError(f"控制 token 不在词表里: {text}")

    def text_of(self, tid: int) -> str:
        for table in (self.structure, self.decisions, self.validations):
            for t, i in table.items():
                if i == tid:
                    return t
        raise ValueError(f"{tid} 不是控制 token")

    def encode_text(self, text: str) -> List[int]:
        for bad in ("<TASK>", "</TASK>", "<CODE>", "</CODE>", "<D:", "<V:"):
            if bad in text:
                raise ValueError(f"任务/代码文本里出现控制标记 {bad!r}，命名空间被污染")
        out: List[int] = []
        i, n = 0, len(text)
        while i < n:
            ch = text[i]
            if ch in self.l0_set:
                out.append(self.index.get(ch, self.unk_id))
                i += 1
                continue
            hit = None
            for tok, tid in self.by_first.get(ch, ()):
                if text.startswith(tok, i):
                    hit = (tok, tid)
                    break
            if hit:
                out.append(hit[1])
                i += len(hit[0])
            else:
                out.append(self.unk_id)
                self.unk_count += 1
                i += 1
        return out

    def decode_text(self, ids: Sequence[int]) -> str:
        out = []
        for i in ids:
            if i == self.pad_id:
                continue
            if i == self.unk_id:
                out.append("\ufffd")
            elif i < len(self.tokens):
                t = self.tokens[i]
                if not (t.startswith("<D:") or t.startswith("<V:") or t.startswith("<")):
                    out.append(t)
        return "".join(out)


def _answer_json(code: str) -> Optional[Any]:
    try:
        return json.loads(code)
    except Exception:
        return None


def rule_decisions(sample: Dict[str, Any], code: str) -> Dict[str, str]:
    """确定性规则派生的**合成**决策标签（仅机制验证，不是真实决策日志）。

    规则只用样本里可复核的字段（答案 JSON、代码长度、任务文本关键字），
    并在 report.md 里逐条列出，便于任何人重算。
    """
    ans = _answer_json(code)
    task = sample["task"]
    cat = str(sample.get("meta", {}).get("category", ""))
    n = len(code)
    d: Dict[str, str] = {}
    if isinstance(ans, dict) and cat == "decision" and ans.get("decision") in ("FR", "RW", "PATCH"):
        d["EDIT"] = str(ans["decision"])
    else:
        d["EDIT"] = "PATCH" if n < 120 else ("FR" if n < 320 else "RW")
    d["PLAN"] = "DECOMPOSE" if isinstance(ans, dict) and len(ans.get("subtasks") or []) >= 3 else "DIRECT"
    d["RETRY"] = "YES" if isinstance(ans, dict) and ans.get("ok") is False else "NO"
    if any(k in task for k in ("删除", "覆盖", "写入", "执行", "运行")):
        d["SAFE"] = "L2"
    elif any(k in task for k in ("文件", "目录", "源码")):
        d["SAFE"] = "L1"
    else:
        d["SAFE"] = "L0"
    diag = str(ans.get("code", "")) if isinstance(ans, dict) else ""
    d["FIX"] = "ADD_TYPE" if diag in ("L2002", "L2003") else (
        "RENAME" if diag in ("L4001", "L4002") else "REFACTOR")
    d["NEXT"] = "TEST" if str(sample.get("meta", {}).get("format")) == "code" else "EDIT"
    d["CTX"] = "FETCH" if len(task) > 120 else ("KEEP" if len(task) > 60 else "DROP")
    return d


def template_key(sample: Dict[str, Any]) -> str:
    """分组切分用的「模板簇」键：类别 + 抹掉可变部分后的 task 文本。

    v2 的 ``stratified_split`` 按 category 随机打散，同一模板的变体跨 train/test，
    decision 类 6 条 test 的 task 在 train 里一字不差出现过（A 组 1.000 是记忆
    不是泛化）。这里把数字/天干占位符归一化，保证同簇样本整体进同一 split。
    """
    s = _TEMPLATE_NUM_RE.sub("#", sample["task"])
    s = _TEMPLATE_VAR_RE.sub("@", s)
    s = re.sub(r"\s+", "", s)
    return f"{sample.get('_category', '')}|{s}"


def decision_window(sample: Dict[str, Any], vocab: Vocab) -> List[int]:
    """scattered 模式在 ``</TASK>`` 与决策 token 之间插入的任务文本窗口。

    **训练与推理必须用同一个窗口**：本函数是唯一真相，``build_ids()`` 与
    ``generate()`` 都调它。v3.1 只改训练侧、推理 prompt 仍止于 ``</TASK>``，
    导致分布不一致，判据 ③ 实测从 0.9808 崩到 0.4808。

    窗口由 ``sha256(task + code)`` 确定性派生，**不依赖调用顺序或 RNG 状态**，
    因此训练与推理两条路径即使在不同进程里也能算出同一窗口。
    """
    task_ids = vocab.encode_text(sample["task"])
    # 末尾 6 个 token 是各模板共有的固定套话（「…输出 JSON。」），排除掉
    # 以免 pos-1 又退化成同一个标点。太短的任务则退回整体。
    usable = task_ids[:-6] if len(task_ids) > 10 else task_ids
    if not usable:
        return []
    seed = hashlib.sha256(
        (sample["task"] + "\x00" + str(sample["steps"][0]["code"])).encode("utf-8")
    ).hexdigest()
    rng = random.Random(int(seed, 16))
    k = rng.randint(1, min(8, len(usable)))
    start = rng.randint(0, len(usable) - k)
    return usable[start:start + k]


def build_ids(sample: Dict[str, Any], vocab: Vocab, policy: str,
              shuffle_rng: Optional[random.Random] = None,
              decision_position: str = "fixed",
              position_rng: Optional[random.Random] = None) -> Tuple[List[int], Dict[str, str]]:
    """一条 Sample -> 统一自回归序列的 id 列表 + 该样本的决策标签。

    ``decision_position``：
    * ``fixed``（v2 行为）：决策 token 紧跟 ``</TASK>``。实测 50/50 条决策 token
      的前一位置都是 ``</TASK>``，pos-1 探针特征退化成常数，测不到「决策前的上下文状态」。
    * ``scattered``：在 ``</TASK>`` 与 ``<CODE>`` 之间插入一段**从任务文本随机位置
      截取**的 token 窗口，再放决策 token，使 pos-1 不再恒等于 ``</TASK>``。
      方案 §7「随机交错三类 token」。

      v3.1 修正：初版用 ``task_tail[-k:]`` 取末尾 k 个 token，但本库 363 条样本
      的 task 全以「输出 JSON。」结尾，实测 48/48 条决策 token 的前一 token
      都是同一个 ``。``(id=46) —— 只是把常数从 ``</TASK>`` 换成了 ``。``。
      改为随机起点截取窗口，并跳过尾部固定套话。
    """
    steps = sample["steps"]
    if not steps:
        raise ValueError("样本 steps 为空")
    code = str(steps[0]["code"])
    validation = str(steps[0].get("validation") or "PASS")
    vtext = f"<V:{validation}>"
    if vtext not in vocab.validations:
        raise ValueError(f"未登记的验证码 {vtext}")
    labels: Dict[str, str] = {}
    if policy == "real":
        # T-0494：样本自带真实决策（runtime 决策快照）时**原样注入每个点**，
        # 不再看 meta.category。_kept_decisions 是密度限量后的子集（见
        # assign_decision_budget），没有则用完整 decisions。
        # 逐点校验 point/option 都在封闭词表里，非法直接报错。
        raw = steps[0].get("_kept_decisions")
        if raw is None:
            raw = steps[0].get("decisions")
        if isinstance(raw, dict) and raw:
            for point, option in raw.items():
                if point not in vocab.point_token_ids:
                    raise ValueError(f"决策点 {point!r} 不在词表 point_token_ids 里")
                tok = f"<D:{point}={option}>"
                if tok not in vocab.decisions:
                    raise ValueError(f"决策标签 {tok} 不在封闭集合里")
                labels[point] = str(option)
        else:
            # 没有自带决策字段才退回旧逻辑（旧库 decision 类从答案 JSON 取 EDIT）
            cat = str(sample.get("meta", {}).get("category", ""))
            ans = _answer_json(code)
            if cat == "decision" and isinstance(ans, dict) and ans.get("decision") in ("FR", "RW", "PATCH"):
                labels["EDIT"] = str(ans["decision"])
    elif policy == "rule":
        labels = rule_decisions(sample, code)
        # 7 个点全注入会让决策密度 ~4.5%，突破方案 §8.5 的 2% 硬上限。
        # 按样本内容做确定性轮转，每条只保留 2 个点：密度 ~1.3%，
        # 且 7 个点在全集上都有正样本，探针不必只靠单点。
        pts = vocab.points
        h = int(hashlib.sha256((sample["task"] + code).encode("utf-8")).hexdigest(), 16)
        start = h % len(pts)
        keep = {pts[(start + j) % len(pts)] for j in range(2)}
        labels = {p: o for p, o in labels.items() if p in keep}
    elif policy == "off":
        labels = {}
    else:
        raise ValueError(f"未知决策策略 {policy}")

    if shuffle_rng is not None:
        shuffled = {}
        for p, opt in labels.items():
            opts = vocab.point_options.get(p, [])
            if len(opts) > 1:
                others = [o for o in opts if o != opt]
                shuffled[p] = shuffle_rng.choice(others)  # 强制换成别的选项
            else:
                shuffled[p] = opt
        labels = shuffled

    ids: List[int] = [vocab.structure["<TASK>"]]
    ids.extend(vocab.encode_text(sample["task"]))
    ids.append(vocab.structure["</TASK>"])
    if decision_position == "scattered" and labels:
        # 把任务文本中一段**随机位置**的 token 窗口挪到 </TASK> 之后，再放决策
        # token。这样 pos-1 既不恒为 </TASK>，也不恒为末尾那句固定套话「输出
        # JSON。」，探针才有机会测到「决策前的上下文状态」。
        #
        # v3.2 关键修正：`generate()` 必须用**同一个窗口**构造 prompt，
        # 否则训练序列在 </TASK> 后多了一段任务文本、推理 prompt 却没有，
        # 属于训练/推理分布不一致。实测它把判据 ③ 从 0.9808 打到 0.4808
        # （52 条里少 26 条合法）。窗口由 decision_window() 确定性产出，并挂到
        # 样本上，供 eval_generation 原样复用（无标签行不插窗口）。
        win = decision_window(sample, vocab)
        sample["_scatter_window"] = win
        ids.extend(win)
    elif decision_position not in ("fixed", "scattered"):
        raise ValueError(f"未知 --decision-position {decision_position}")
    for p in vocab.points:
        if p in labels:
            t = f"<D:{p}={labels[p]}>"
            if t not in vocab.decisions:
                raise ValueError(f"决策标签 {t} 不在封闭集合里")
            ids.append(vocab.decisions[t])
    ids.append(vocab.structure["<CODE>"])
    ids.extend(vocab.encode_text("\n" + code + "\n"))
    ids.append(vocab.structure["</CODE>"])
    ids.append(vocab.validations[vtext])
    return ids, labels


def strip_controls(ids: Sequence[int], vocab: Vocab) -> List[int]:
    """B 组消融：删掉决策 + 验证 token，只留任务/代码与 4 个结构标记。"""
    return [i for i in ids if i not in vocab.decision_ids and i not in vocab.validation_ids]


def load_samples(payload: Dict[str, Any]) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    for key in ("json_tasks", "code_tasks", "err_tasks"):
        text = payload.get(key, "")
        if not text:
            continue
        for lineno, line in enumerate(text.splitlines(), 1):
            if not line.strip():
                continue
            r = json.loads(line)
            if not r.get("task") or not r.get("steps"):
                raise ValueError(f"{key}:{lineno} 缺 task/steps")
            r["_source_file"] = key
            r["_category"] = str(r.get("meta", {}).get("category") or key)
            r["_format"] = str(r.get("meta", {}).get("format") or "code")
            rows.append(r)

    # ---- T-0494：runtime 决策快照 -> 样本 ----------------------------------
    # 每条真实决策日志转成一个样本。字段缺失或验证码未登记一律抛错，
    # 绝不静默丢行：宁可训练起不来，也不能让「241 条决策又悄悄失踪」。
    dec_text = payload.get("decisions", "")
    if dec_text:
        # 词表引用由调用方构造后挂进来；没有则按 payload 的 control_layout 校验
        known_validations = set(_decision_validation_tokens(payload.get("vocab") or {}))
        for lineno, line in enumerate(dec_text.splitlines(), 1):
            if not line.strip():
                continue
            r = json.loads(line)
            missing = [k for k in ("task_text", "source", "validation_code", "decisions")
                       if not r.get(k)]
            if missing:
                raise ValueError(f"decisions:{lineno} 缺字段 {missing}，拒绝静默丢行")
            if not isinstance(r["decisions"], dict) or not r["decisions"]:
                raise ValueError(f"decisions:{lineno} decisions 不是非空 dict")
            vtext = f"<V:{r['validation_code']}>"
            if vtext not in known_validations:
                raise ValueError(f"decisions:{lineno} 未登记的验证码 {vtext}")
            rows.append({
                "task": str(r["task_text"]),
                "steps": [{
                    "code": str(r["source"]),
                    "validation": str(r["validation_code"]),
                    "decisions": dict(r["decisions"]),
                }],
                "meta": {"template": str(r.get("template_id") or ""),
                         "category": "runtime_decision"},
                "_source_file": "decisions",
                "_category": "runtime_decision",
                "_format": "code",
                "_decision_row": True,
            })
    if rows and dec_text:
        # 限量下沉到这里，保证所有调用路径（self_check / build_ids / 测试）
        # 都看到同一份「每样本 1 点」的决策集；诊断挂到 payload.meta，
        # main() 与报告都能读到，不重复计算。
        vocab_for_budget = Vocab(payload["vocab"])
        payload.setdefault("meta", {})["decision_budget"] = decision_budget(
            rows, vocab_for_budget)
    return rows


def _decision_validation_tokens(vocab_data: Dict[str, Any]) -> List[str]:
    """从 payload 的 vocab 段读取已登记的验证码 token（无需构造完整 Vocab）。"""
    lay = vocab_data.get("control_layout") or {}
    return list((lay.get("validations") or {}).keys())


def decision_budget(rows: Sequence[Dict[str, Any]], vocab: Vocab,
                    max_density: float = DENSITY_MAX) -> Dict[str, Any]:
    """T-0494：给 runtime 决策样本做 **sha256 派生的确定性限量**。

    241 条决策样本若把 6~7 个点全量注入，训练序列决策密度实测 0.0780，
    超 ``DENSITY_MAX=0.02`` 近 4 倍。这里按样本内容 sha256 确定性选点，
    默认每条只留 1 个点（密度 ~0.014，达标）；两条例外：

    * 稀有点（FIX，只在 10 条重试记录里）：保留它的样本不参与轮转，
      保证该点始终有正样本；
    * 若某点在全部样本里出现次数不足以让 7 点都覆盖，按出现次数从多到少
      逐点补留，直到 7 点都有正样本或样本耗尽。

    结果写回每条样本的 ``steps[0]["_kept_decisions"]``。函数只读样本，
    返回诊断 dict；**不修改 vocab、不修改任何判据阈值**。
    """
    dec_rows = [r for r in rows if r.get("_decision_row")]
    if not dec_rows:
        return {"n_decision_rows": 0, "per_point_kept": {}, "strategy": "no_decision_rows"}

    # 每条样本按 sha256(task + code) 确定性轮转一个主点；FIX 稀有优先留守。
    baseline: Dict[int, str] = {}
    for r in dec_rows:
        full = r["steps"][0]["decisions"]
        h = int(hashlib.sha256(
            (r["task"] + "\x00" + str(r["steps"][0]["code"])).encode("utf-8")
        ).hexdigest(), 16)
        ordered = sorted(full, key=lambda p: (hashlib.sha256(
            (str(h) + "\x00" + p).encode("utf-8")).hexdigest(), p))
        baseline[id(r)] = ordered[0]

    kept_counts: Dict[str, int] = defaultdict(int)
    for r in dec_rows:
        p = baseline[id(r)]
        r["steps"][0]["_kept_decisions"] = {p: r["steps"][0]["decisions"][p]}
        kept_counts[p] += 1

    # 稀有点保底：FIX 全量只有 10 条、集中在 3 个模板簇。轮转很可能一条都不
    # 选它，或只选中的那几条恰好切到同一侧，导致探针某侧无 train 样本可 fit。
    # 这里让**每个含 FIX 的样本都保留 FIX 点**（真实日志里它本就是该条决策的一部分，
    # 不是伪造）：配合 stratified_split 的簇级奇偶交替，train/test 两侧都必有 FIX
    # 正样本。代价是多留 ≤10 个决策 token，密度影响可忽略（实测仍 ~0.0043）。
    for r in dec_rows:
        full = r["steps"][0]["decisions"]
        for rare in ("FIX",):
            if rare in full:
                cur = next(iter(r["steps"][0]["_kept_decisions"]), None)
                if cur != rare:
                    if cur in kept_counts and kept_counts[cur] > 0:
                        kept_counts[cur] -= 1
                    r["steps"][0]["_kept_decisions"] = {rare: full[rare]}
                    kept_counts[rare] = kept_counts.get(rare, 0) + 1

    # 全量密度复核：留 1 点仍超上限时（极端样本集）不再自动加码，
    # 交由调用方断言失败——不许偷偷改 DENSITY_MAX。
    full_dec = sum(len(r["steps"][0]["decisions"]) for r in dec_rows)
    kept_dec = sum(len(r["steps"][0]["_kept_decisions"]) for r in dec_rows)
    return {
        "n_decision_rows": len(dec_rows),
        "decision_tokens_full": full_dec,
        "decision_tokens_kept": kept_dec,
        "per_point_kept": dict(sorted(kept_counts.items())),
        "strategy": "sha256_rotate_1point_with_rare_floor",
        "max_density": max_density,
    }


def stratified_split(rows: Sequence[Dict[str, Any]], seed: int,
                     group_split: bool = False,
                     coverage: Optional[Dict[str, Any]] = None) -> Dict[str, List[Dict[str, Any]]]:
    """按类别（或类别+模板簇）切 train/val/test。

    ``group_split=True`` 时同一 ``template_key`` 的变体整体进同一 split，
    避免 v2 里「decision 类 6 条 test 的 task 在 train 里一字不差出现」的泄漏。
    分组以 **cluster 为单位** 做 70/15/15，样本数会与 v2 的逐样本切分略有差异。

    T-0494：含稀有决策点（FIX）的模板簇在 train/test 之间做确定性交错，
    保证稀有点两侧都有正样本——不靠换 seed 试，仍以簇为单位所以 overlap 恒 0。
    """
    if group_split:
        by: Dict[str, List[Dict[str, Any]]] = defaultdict(list)
        for r in rows:
            by[template_key(r)].append(r)
        clusters = list(by.values())
    else:
        by = defaultdict(list)
        for r in rows:
            by[r["_category"]].append(r)
        clusters = [[r] for r in sum(by.values(), [])]  # 每个样本自成一簇 = v2 行为

    rng = random.Random(seed)
    rng.shuffle(clusters)
    out: Dict[str, List[Dict[str, Any]]] = {"train": [], "val": [], "test": []}
    n_clusters = len(clusters)
    n_tr = max(1, int(round(n_clusters * 0.70)))
    n_va = max(1, int(round(n_clusters * 0.15))) if n_clusters >= 7 else 0
    for i, cl in enumerate(clusters):
        name = "train" if i < n_tr else ("val" if i < n_tr + n_va else "test")
        out[name].extend(cl)
    if not out["test"] and n_clusters > 2:
        out["test"].extend(out["train"][:1])
        out["train"] = out["train"][1:]
    for k in out:
        rng.shuffle(out[k])

    # ---- T-0494 稀有点双侧保底（确定性，不动 overlap） --------------------
    # FIX 点只在 list_index 家族的 3 个模板簇；纯随机 70/15/15 会随 seed 漂移，
    # 有的 seed 把 FIX 全留在 train，探针 test 侧就无该点样本。做一次**簇级**
    # 修复：收集所有含 FIX 的簇，按 template_key 排序，第 1 个钉到 train、
    # 第 2 个钉到 test。迁移以簇为单位（绝不拆分），故 overlap 恒为 0。
    if group_split and n_va > 0 and any(r.get("_decision_row") for r in rows):
        rare = "FIX"
        rare_keys = {
            template_key(r) for side in ("train", "val", "test") for r in out[side]
            if r.get("_decision_row") and rare in r["steps"][0].get("decisions", {})
        }
        # 整簇收集（同簇的非 FIX 行也要跟着走，否则样本会丢），按 template_key 聚合
        rare_clusters: Dict[str, List[Dict[str, Any]]] = {}
        for side in ("train", "val", "test"):
            for r in out[side]:
                if template_key(r) in rare_keys:
                    rare_clusters.setdefault(template_key(r), []).append(r)
        ordered_keys = sorted(rare_clusters)
        # 先把这些簇从各自 split 中摘掉
        for side in ("train", "val", "test"):
            out[side] = [r for r in out[side] if template_key(r) not in rare_clusters]
        # 按确定性顺序奇偶交替钉到 train / test：两侧都有该点样本，
        # 每个簇只落一侧（无重复 -> overlap 恒 0），样本总数守恒。
        # 只有 1 个簇时无法同时满足两侧，此时整簇留 train，交给门禁如实拦，
        # 绝不复制 test 样本或伪造标签。
        for i, key in enumerate(ordered_keys):
            out["train" if (i % 2 == 0 or len(ordered_keys) == 1) else "test"].extend(
                rare_clusters[key])
        for k in out:
            rng.shuffle(out[k])

    if coverage is not None:
        tr_keys = {template_key(r) for r in out["train"]}
        te_keys = {template_key(r) for r in out["test"]}
        va_keys = {template_key(r) for r in out["val"]}
        coverage.update({
            "group_split": group_split,
            "n_clusters": n_clusters,
            "train_test_template_overlap": len(tr_keys & te_keys),
            "val_test_template_overlap": len(va_keys & te_keys),
            "n_templates": len(by),
            "splits": {k: len(v) for k, v in out.items()},
        })
    return out


def label_coverage(splits, seqs, vocab: Vocab) -> Dict[str, Any]:
    """门禁所需的覆盖率诊断（纯标准库，可在训练前算出）。"""
    def stats(name):
        dec = [i for s in seqs[name] for i in s if i in vocab.decision_ids]
        by_point = defaultdict(int)
        for i in dec:
            by_point[DECISION_RE.fullmatch(vocab.text_of(i)).group(1)] += 1  # type: ignore[union-attr]
        vals = {vocab.text_of(i).replace("<V:", "").replace(">", "")
                for s in seqs[name] for i in s if i in vocab.validation_ids}
        return {"n_decision_tokens": len(dec), "points": dict(by_point),
                "validation_codes": sorted(vals)}
    tr, te = stats("train"), stats("test")
    points_all = sorted(set(tr["points"]) | set(te["points"]))
    return {
        "train": tr, "test": te,
        "points_with_any_label": points_all,
        "points_with_test_labels": sorted(te["points"]),
        "n_points_with_test_labels": len(te["points"]),
        "n_test_decision_rows": sum(1 for s in seqs["test"]
                                    if any(i in vocab.decision_ids for i in s)),
        "validation_codes_seen": sorted(set(tr["validation_codes"]) | set(te["validation_codes"])),
        "has_err_validation": any(c != "PASS" for c in
                                  set(tr["validation_codes"]) | set(te["validation_codes"])),
    }


def make_batches(seqs: Sequence[Sequence[int]], vocab: Vocab, seq_len: int,
                 batch_size: int, control_weight: float, rng: random.Random,
                 limit: Optional[int] = None) -> List[Dict[str, Any]]:
    order = list(range(len(seqs)))
    rng.shuffle(order)
    batches: List[Dict[str, Any]] = []
    truncated = 0
    for start in range(0, len(order), batch_size):
        if limit is not None and len(batches) >= limit:
            break
        rows_x: List[List[int]] = []
        rows_y: List[List[int]] = []
        rows_w: List[List[float]] = []
        for idx in order[start:start + batch_size]:
            ids = list(seqs[idx])[:seq_len + 1]
            if len(list(seqs[idx])) > seq_len + 1:
                truncated += 1
            x, y = ids[:-1], ids[1:]
            w = [0.0 if t == vocab.pad_id else
                 (control_weight if vocab.kind_of(t) in ("structure", "decision", "validation")
                  else 1.0) for t in y]
            pad = seq_len - len(x)
            rows_x.append(x + [vocab.pad_id] * pad)
            rows_y.append(y + [vocab.pad_id] * pad)
            rows_w.append(w + [0.0] * pad)
        batches.append({"x": rows_x, "y": rows_y, "w": rows_w})
    return batches


def dataset_stats(seqs: Sequence[Sequence[int]], vocab: Vocab) -> Dict[str, Any]:
    total = sum(len(s) for s in seqs)
    dec = sum(1 for s in seqs for i in s if i in vocab.decision_ids)
    val = sum(1 for s in seqs for i in s if i in vocab.validation_ids)
    st = sum(1 for s in seqs for i in s if i in vocab.structure_ids)
    # 只数「传入的这批序列」里的 UNK id。v1 读的是 Vocab.unk_count 全局累积
    # 计数器，会把其它 split 与 shuffle 组重复构建的 UNK 也算进来，
    # 结果随调用次数翻倍（本机 77 / OpenI 154），不可复现。
    unk = sum(1 for s in seqs for i in s if i == vocab.unk_id)
    return {
        "samples": len(seqs), "tokens": total,
        "decision_tokens": dec, "validation_tokens": val, "structure_tokens": st,
        "decision_density": round(dec / max(total, 1), 6),
        "decision_density_ok": dec / max(total, 1) <= DENSITY_MAX,
        "mean_len": round(total / max(len(seqs), 1), 1),
        "max_len": max((len(s) for s in seqs), default=0),
        "unk_tokens": unk,
        "unk_ratio": round(unk / max(total, 1), 6),
        "unk_ratio_scope": "训练序列 token 口径（与词表报告的字符级 UNK 率不同）",
        "validation_codes_seen": sorted({vocab.text_of(i).replace("<V:", "").replace(">", "")
                                         for s in seqs for i in s if i in vocab.validation_ids}),
    }


# ===========================================================================
# 2. torch 层：模型（与 src/lightprism/model.py 同构）
# ===========================================================================
class PrismModel:
    """延迟构建 torch 模块，保证 --self-check 在无 torch 环境下可跑。"""

    def __init__(self, vocab_size: int, preset: Dict[str, Any], dropout: float = 0.0,
                 seed: int = 0) -> None:
        import torch
        import torch.nn as nn
        import torch.nn.functional as F

        torch.manual_seed(seed)
        dim = preset["dim"]
        n_layers, n_heads = preset["n_layers"], preset["n_heads"]
        head_dim = dim // n_heads
        if dim % n_heads:
            raise ValueError(f"dim={dim} 不能被 n_heads={n_heads} 整除")
        hidden_ffn = max(int(round(dim * preset["ffn_mult"] * 2 / 3 / 64)) * 64, 64)

        class RMSNorm(nn.Module):
            def __init__(self, d: int, eps: float = 1e-6):
                super().__init__()
                self.weight = nn.Parameter(torch.ones(d))
                self.eps = eps

            def forward(self, x):
                # fp32 累加 + 缩放，再转回激活 dtype（AMP 下权重不降精度）
                h = x.float()
                out = h * torch.rsqrt(h.pow(2).mean(-1, keepdim=True) + self.eps)
                return (out * self.weight).to(x.dtype)

        def rope(t: int, start: int = 0):
            inv = 1.0 / (10000.0 ** (torch.arange(0, head_dim, 2, device=rope.dev).float() / head_dim))
            pos = torch.arange(start, start + t, device=rope.dev).float()
            f = torch.outer(pos, inv)
            return f.cos(), f.sin()

        rope.dev = None  # type: ignore[attr-defined]

        def apply_rope(x, cos, sin):
            cos, sin = cos.to(x.dtype), sin.to(x.dtype)
            x1, x2 = x[..., : x.shape[-1] // 2], x[..., x.shape[-1] // 2:]
            rot = torch.cat((-x2, x1), dim=-1)
            return x * torch.cat((cos, cos), dim=-1) + rot * torch.cat((sin, sin), dim=-1)

        def sdpa(q, k, v, is_causal: bool, attn_mask=None):
            if hasattr(F, "scaled_dot_product_attention"):
                kwargs = {"dropout_p": 0.0, "is_causal": is_causal, "attn_mask": attn_mask}
                if attn_mask is not None:
                    kwargs["is_causal"] = False
                return F.scaled_dot_product_attention(q, k, v, **kwargs)
            scores = q @ k.transpose(-2, -1) / math.sqrt(q.size(-1))
            if attn_mask is not None:
                scores = scores.masked_fill(~attn_mask, float("-inf"))
            elif is_causal:
                m = torch.ones(q.size(-2), k.size(-2), dtype=torch.bool, device=q.device).tril()
                scores = scores.masked_fill(~m, float("-inf"))
            return torch.softmax(scores.float(), -1).to(q.dtype) @ v

        class Attention(nn.Module):
            def __init__(self):
                super().__init__()
                self.qkv = nn.Linear(dim, 3 * dim, bias=False)
                self.proj = nn.Linear(dim, dim, bias=False)
                self.qn, self.kn = RMSNorm(head_dim), RMSNorm(head_dim)
                self.drop = nn.Dropout(dropout)

            def step(self, x, cos, sin, past):
                b, t, _ = x.shape
                q, k, v = self.qkv(x).split(dim, dim=2)
                q = q.view(b, t, n_heads, head_dim).transpose(1, 2)
                k = k.view(b, t, n_heads, head_dim).transpose(1, 2)
                v = v.view(b, t, n_heads, head_dim).transpose(1, 2)
                q, k = self.qn(q), self.kn(k)          # QK-Norm
                q, k = apply_rope(q, cos, sin), apply_rope(k, cos, sin)
                if past is None:
                    nk, nv = k, v
                    o = sdpa(q, k, v, True)
                else:
                    pk, pv = past
                    nk, nv = torch.cat([pk, k], 2), torch.cat([pv, v], 2)
                    if t == 1:
                        o = sdpa(q, nk, nv, False)
                    else:
                        mask = torch.ones(t, nk.size(2), dtype=torch.bool, device=x.device).tril(
                            diagonal=pk.size(2))
                        o = sdpa(q, nk, nv, False, mask)
                o = o.transpose(1, 2).contiguous().view(b, t, dim)
                return self.drop(self.proj(o)), (nk, nv)

        class Block(nn.Module):
            def __init__(self):
                super().__init__()
                self.n1, self.n2 = RMSNorm(dim), RMSNorm(dim)
                self.attn = Attention()
                self.w1 = nn.Linear(dim, hidden_ffn, bias=False)
                self.w3 = nn.Linear(dim, hidden_ffn, bias=False)
                self.w2 = nn.Linear(hidden_ffn, dim, bias=False)
                self.drop = nn.Dropout(dropout)

            def step(self, x, cos, sin, past):
                a, kv = self.attn.step(self.n1(x), cos, sin, past)
                x = x + a
                n = self.n2(x)
                return x + self.drop(self.w2(F.silu(self.w1(n)) * self.w3(n))), kv

        class Model(nn.Module):
            def __init__(self):
                super().__init__()
                self.embed = nn.Embedding(vocab_size, dim)
                self.blocks = nn.ModuleList([Block() for _ in range(n_layers)])
                self.nf = RMSNorm(dim)
                self.head = nn.Linear(dim, vocab_size, bias=False)
                self.head.weight = self.embed.weight        # tied embedding
                for m in self.modules():
                    if isinstance(m, nn.Linear):
                        nn.init.normal_(m.weight, 0.0, 0.02)
                nn.init.normal_(self.embed.weight, 0.0, 0.02)
                self.cfg = dict(vocab_size=vocab_size, **preset, dropout=dropout)

            def body(self, ids, past=None):
                b, t = ids.shape
                cache = past[0][0].size(2) if past else 0
                if t + cache > preset["max_seq"]:
                    raise ValueError(f"序列 {t + cache} 超过 max_seq={preset['max_seq']}")
                rope.dev = ids.device
                cos, sin = rope(t, cache)
                x = self.embed(ids)
                kv = []
                for i, blk in enumerate(self.blocks):
                    x, k = blk.step(x, cos, sin, past[i] if past else None)
                    kv.append(k)
                return self.nf(x), kv

            def forward(self, ids, targets=None, weights=None, return_hidden=False):
                h, _ = self.body(ids)
                logits = self.head(h)
                loss = None
                if targets is not None:
                    ce = torch.nn.functional.cross_entropy(
                        logits.reshape(-1, vocab_size).float(), targets.reshape(-1),
                        reduction="none").view_as(targets)
                    if weights is not None:
                        loss = (ce * weights).sum() / weights.sum().clamp(min=1.0)
                    else:
                        loss = ce.mean()
                return logits, loss, (h if return_hidden else None)

            def incremental(self, ids, past=None):
                h, kv = self.body(ids, past)
                return self.head(h), kv

            def n_params(self, non_embedding=False):
                n = sum(p.numel() for p in self.parameters())
                return n - self.embed.weight.numel() if non_embedding else n

        self.torch = torch
        self.net = Model()
        self.dim = dim
        self.head_dim = head_dim
        print(f"[model] preset={preset} params={self.net.n_params():,} "
              f"(non-embedding {self.net.n_params(True):,}) vocab={vocab_size}")


def to_device(batch: Dict[str, Any], torch, device, vocab: Vocab):
    x = torch.tensor(batch["x"], dtype=torch.long, device=device)
    y = torch.tensor(batch["y"], dtype=torch.long, device=device)
    w = torch.tensor(batch["w"], dtype=torch.float32, device=device)
    return x, y, w


def grad_norms(model: PrismModel, vocab: Vocab) -> Dict[str, float]:
    """按 token 类型分组的嵌入梯度范数（方案 §8.6 要求，骨架里缺的这一条）。"""
    g = model.net.embed.weight.grad
    if g is None:
        return {}
    return {
        "grad_norm_all": round(float(g.norm()), 5),
        "grad_norm_text_rows": round(float(g[:vocab.ctrl_start].norm()), 5),
        "grad_norm_control_rows": round(float(g[vocab.ctrl_start:vocab.ctrl_end].norm()), 5),
    }


def grad_norm_summary(history: Sequence[Dict[str, Any]]) -> Dict[str, Any]:
    """方案 §8.6：按 token 类型监控梯度范数，给出控制/文本行比值摘要。"""
    pairs = [(r.get("grad_norm_control_rows"), r.get("grad_norm_text_rows"))
             for r in history if r.get("grad_norm_control_rows") and r.get("grad_norm_text_rows")]
    ratios = [c / t for c, t in pairs if t and t > 0]
    if not ratios:
        return {"status": "no_data"}
    ratios.sort()
    return {"n_steps": len(ratios),
            "control_over_text_ratio_mean": round(sum(ratios) / len(ratios), 4),
            "control_over_text_ratio_max": round(ratios[-1], 4),
            "control_over_text_ratio_p50": round(ratios[len(ratios) // 2], 4),
            "note": "§8.6：若决策 token 梯度持续显著高于代码 token，说明损失权重失衡"}


def embedding_geometry(model: PrismModel, vocab: Vocab, seqs: Sequence[Sequence[int]],
                       torch) -> Dict[str, Any]:
    """方案 §7 阶段一检查点：决策 token 嵌入是否与代码 token 落入同一可分空间。

    v3.1 修正：模型是 **tied embedding**（``head.weight is embed.weight``），
    输出 softmax 每一步会给**每一个**词表行送梯度。本机实测一步前反后
    ``embed.grad`` 非零行数 = 2902/2902，19 个决策 token 行全部有梯度，
    包括那 16 个「从未作为输入出现」的。所以旧字段名
    ``never_trained`` / 「16 个死权重」是错的：它们只是**从未作为输入**，
    权重一直在动。余弦 mean 从 0.0004 涨到 0.3771 主要来自 softmax 把
    所有行往同一方向推，**不能当作「进入同一语义场」的正面证据**。
    """
    net = model.net
    with torch.no_grad():
        e = net.embed.weight.detach().float().cpu()
    seen_dec = {i for s in seqs for i in s if i in vocab.decision_ids}
    dec_ids = sorted(vocab.decision_ids)
    unseen = [i for i in dec_ids if i not in seen_dec]
    text_ids = list(range(min(vocab.ctrl_start, 512)))  # 抽样，避免 O(vocab^2)
    e_text_n = e[text_ids] / e[text_ids].norm(dim=1, keepdim=True).clamp(min=1e-8)

    def cos_stats(ids: Sequence[int]) -> Dict[str, Any]:
        if not ids:
            return {"n": 0}
        ed = e[list(ids)]
        ed_n = ed / ed.norm(dim=1, keepdim=True).clamp(min=1e-8)
        vals = (ed_n @ e_text_n.T).flatten().tolist()
        vals.sort()
        return {"n": len(ids),
                "min": round(vals[0], 4),
                "p50": round(vals[len(vals) // 2], 4),
                "max": round(vals[-1], 4),
                "mean": round(sum(vals) / len(vals), 4)}

    return {
        "n_decision_tokens": len(dec_ids),
        "n_decision_tokens_seen_as_input": len(seen_dec),
        "n_decision_tokens_never_seen_as_input": len(unseen),
        "never_seen_as_input_examples": [vocab.text_of(i) for i in unseen][:8],
        "tied_embedding": getattr(net, "head", None) is not None
                          and net.head.weight is net.embed.weight,
        "cosine_dec_vs_text_all": cos_stats(dec_ids),
        "cosine_dec_vs_text_seen_as_input": cos_stats(sorted(seen_dec)),
        "cosine_dec_vs_text_never_seen": cos_stats(unseen),
        "n_text_rows_sampled": len(text_ids),
        "note": "§7 检查点：tied embedding 下所有词表行都从输出 softmax 拿到梯度，"
                "「never_seen_as_input」不等于权重没动；余弦整体升高也不能单独证明"
                "「进入同一语义场」。判共存应看 seen_as_input 子集与文本行的分布差异，"
                "并结合探针准确率，而非只看 overall 均值",
    }


def train_group(model: PrismModel, batches_by_epoch, val_batches, vocab: Vocab,
                device, cfg, autocast, scaler, torch, tag: str,
                out_dir: Path, kind_table) -> Dict[str, Any]:
    """训练一个组，val loss 最优即存 checkpoint，返回训练摘要。"""
    net = model.net
    try:
        opt = torch.optim.AdamW(net.parameters(), lr=cfg["lr"],
                                weight_decay=cfg["weight_decay"], betas=(0.9, 0.95),
                                fused=(device.type == "cuda"))
    except TypeError:  # 老版本无 fused
        opt = torch.optim.AdamW(net.parameters(), lr=cfg["lr"],
                                weight_decay=cfg["weight_decay"], betas=(0.9, 0.95))
    total_batches = sum(len(b) for b in batches_by_epoch)
    warmup = max(1, int(total_batches * cfg["warmup_ratio"]))
    history: List[Dict[str, Any]] = []
    best = {"val_loss": float("inf"), "epoch": -1}
    t0 = time.time()
    step = 0
    log_fh = (out_dir / "train_log.jsonl").open("a", encoding="utf-8")

    def evaluate_val() -> float:
        net.eval()
        tot, n = 0.0, 0
        with torch.no_grad():
            for b in val_batches:
                x, y, w = to_device(b, torch, device, vocab)
                with autocast():
                    _, loss, _ = net(x, y, w)
                tot += float(loss)
                n += 1
        net.train()
        return tot / max(n, 1)

    try:
        net.train()
        for epoch, batches in enumerate(batches_by_epoch):
            for bi, b in enumerate(batches):
                lr = cfg["lr"] * (step + 1) / warmup if step < warmup else \
                    cfg["lr"] * (cfg["min_lr_ratio"] + (1 - cfg["min_lr_ratio"]) * 0.5 *
                                 (1 + math.cos(math.pi * (step - warmup) /
                                               max(total_batches - warmup, 1))))
                for g in opt.param_groups:
                    g["lr"] = lr
                x, y, w = to_device(b, torch, device, vocab)
                with autocast():
                    logits, loss, _ = net(x, y, w)
                if scaler is not None:
                    scaler.scale(loss).backward()
                    scaler.unscale_(opt)
                else:
                    loss.backward()
                norms = grad_norms(model, vocab)
                torch.nn.utils.clip_grad_norm_(net.parameters(), cfg["grad_clip"])
                if scaler is not None:
                    scaler.step(opt)
                    scaler.update()
                else:
                    opt.step()
                opt.zero_grad(set_to_none=True)
                kinds = kind_table[y]
                with torch.no_grad():
                    pred = logits.argmax(-1)
                    keep = w > 0
                    accs = {}
                    for name, kid in vocab.KIND.items():
                        m = keep & (kinds == kid)
                        if int(m.sum()) > 0:
                            accs[name + "_acc"] = round(float((pred[m] == y[m]).float().mean()), 4)
                step += 1
                if step % cfg["log_every"] == 0 or step == 1:
                    rec = {"group": tag, "epoch": epoch, "step": step,
                           "loss": round(float(loss.detach()), 5), "lr": round(lr, 8),
                           "elapsed_s": round(time.time() - t0, 1), **norms, **accs}
                    history.append(rec)
                    log_fh.write(json.dumps(rec, ensure_ascii=False) + "\n")
                    log_fh.flush()
                    print(f"[{tag}] ep{epoch} step {step}/{total_batches} "
                          f"loss={rec['loss']:.4f} decision_acc={accs.get('decision_acc', '-')}")
            vl = evaluate_val()
            if vl < best["val_loss"]:
                best = {"val_loss": vl, "epoch": epoch}
                torch.save({"model": net.state_dict(), "config": net.cfg,
                            "epoch": epoch, "tag": tag, "val_loss": vl},
                           out_dir / "checkpoints" / f"{tag}_best.pt")
            if cfg.get("epoch_limit") and epoch + 1 >= cfg["epoch_limit"]:
                break
    finally:
        log_fh.close()
    return {"tag": tag, "steps": step, "best_val_loss": round(best["val_loss"], 5),
            "best_epoch": best["epoch"], "elapsed_s": round(time.time() - t0, 1),
            "final_train_loss": history[-1]["loss"] if history else None,
            "history": history}


# ===========================================================================
# 3. 评估：生成 / 结构 / 探针 / 外挂基线
# ===========================================================================
def allowed_next(history: Sequence[int], vocab: Vocab) -> Optional[List[int]]:
    """结构状态机（与 src/lightprism/tokenizer.py::allowed_next 同口径）。"""
    st = vocab.structure
    in_task = in_code = False
    last: Optional[int] = None
    used_points = set()
    for i in history:
        if i == st["<TASK>"]:
            in_task, last = True, i
        elif i == st["</TASK>"]:
            in_task, last = False, i
        elif i == st["<CODE>"]:
            in_code, last = True, i
        elif i == st["</CODE>"]:
            in_code, last = False, i
        elif i in vocab.decision_ids:
            last = i
            t = vocab.text_of(i)
            used_points.add(DECISION_RE.fullmatch(t).group(1))  # type: ignore[union-attr]
        elif i in vocab.validation_ids:
            last, used_points = i, set()
    v_ids = sorted(vocab.validation_ids)
    if in_task:
        return [st["</TASK>"]]
    if in_code:
        return [st["</CODE>"]]
    if last is None or last == st["<TASK>"]:
        return [st["</TASK>"]] if last == st["<TASK>"] else [st["<TASK>"]]
    if last == st["</CODE>"]:
        return v_ids
    if last == st["<CODE>"]:
        return [st["</CODE>"]]
    free = [i for p, ids in vocab.point_token_ids.items() if p not in used_points for i in ids]
    return sorted(free + [st["<CODE>"]])


def check_structure(gen_ids: Sequence[int], vocab: Vocab, expect_validation: bool) -> Tuple[bool, List[str]]:
    """无外部状态机、只看模型自己吐出的 id 序列做结构复核。"""
    st = vocab.structure
    problems: List[str] = []
    code_open = code_close = 0
    seen_points = set()
    in_code = False
    last_ctrl = None
    for tid in gen_ids:
        if tid == st["<TASK>"] or tid == st["</TASK>"]:
            problems.append("生成段里出现 TASK 标记")
        elif tid == st["<CODE>"]:
            code_open += 1
            in_code = True
        elif tid == st["</CODE>"]:
            code_close += 1
            in_code = False
        elif tid in vocab.decision_ids:
            if in_code:
                problems.append("决策 token 出现在 CODE 段内（命名空间被污染）")
            p = DECISION_RE.fullmatch(vocab.text_of(tid)).group(1)  # type: ignore[union-attr]
            if p in seen_points:
                problems.append(f"决策点 {p} 同一步重复选择")
            seen_points.add(p)
        elif tid in vocab.validation_ids:
            if in_code:
                problems.append("验证 token 出现在 CODE 段内")
            if last_ctrl != st["</CODE>"]:
                problems.append("验证 token 没有紧跟 </CODE>")
        if tid in vocab.control_ids:
            last_ctrl = tid
    if code_open != 1 or code_close != 1:
        problems.append(f"CODE 标记数不对 open={code_open} close={code_close}")
    if in_code:
        problems.append("CODE 段未闭合")
    if expect_validation:
        if not gen_ids or gen_ids[-1] not in vocab.validation_ids:
            problems.append("结尾不是 <V:...>")
    elif not gen_ids or gen_ids[-1] != st["</CODE>"]:
        problems.append("结尾不是 </CODE>")
    return (not problems), problems


def generate(model: PrismModel, vocab: Vocab, sample: Dict[str, Any], device,
             torch, autocast, max_new: int, constrained: bool,
             expect_validation: bool,
             prompt_extra: Optional[Sequence[int]] = None) -> Dict[str, Any]:
    """``prompt_extra`` 必须与训练时 ``decision_window()`` 产出的窗口一致。

    scattered 模式下训练序列在 ``</TASK>`` 后插了任务文本窗口；推理若不插，
    模型看到的是训练中从未出现过的上下文，生成质量会断崖式下跌。
    """
    net = model.net
    net.eval()
    st = vocab.structure
    prompt = ([st["<TASK>"]] + vocab.encode_text(sample["task"]) + [st["</TASK>"]]
              + list(prompt_extra or []))
    ids = list(prompt)
    generated: List[int] = []
    past = None
    t0 = time.time()
    with torch.no_grad():
        window = torch.tensor([ids], dtype=torch.long, device=device)
        with autocast():
            logits, past = net.incremental(window)
        last = logits[0, -1, :]
        for _ in range(max_new):
            logits = last.clone()
            if constrained:
                allow = allowed_next(ids, vocab)
                if allow is not None:
                    s = set(allow)
                    blocked = [i for i in vocab.control_ids if i not in s]
                    if blocked:
                        logits[torch.tensor(blocked, dtype=torch.long, device=device)] = float("-inf")
            nxt = int(torch.argmax(logits).item())
            ids.append(nxt)
            generated.append(nxt)
            stop = (nxt in vocab.validation_ids) if expect_validation else (nxt == st["</CODE>"])
            if stop or len(ids) >= net.cfg["max_seq"]:
                break
            with autocast():
                lg, past = net.incremental(
                    torch.tensor([[nxt]], dtype=torch.long, device=device), past)
            last = lg[0, -1, :]
    elapsed = max(time.time() - t0, 1e-6)
    ok, problems = check_structure(generated, vocab, expect_validation)
    truncated = len(generated) >= max_new
    # 抽出 CODE 段文本
    code_ids: List[int] = []
    inside = False
    for i in generated:
        if i == st["<CODE>"]:
            inside = True
            continue
        if i == st["</CODE>"]:
            break
        if inside:
            code_ids.append(i)
    code_text = vocab.decode_text(code_ids).strip()
    ans = _answer_json(str(sample["steps"][0]["code"]))
    gen_json = _answer_json(code_text)
    j_valid = gen_json is not None
    j_exact = j_valid and ans is not None and gen_json == ans
    return {
        "structure_ok": ok, "structure_problems": problems, "truncated": truncated,
        "counts_toward_structure_rate": ok and not truncated,
        "code_text": code_text, "answer_text": str(sample["steps"][0]["code"]),
        "json_valid": j_valid, "json_exact": j_exact,
        "is_json_task": sample["_format"] == "json",
        "n_decision": sum(1 for i in generated if i in vocab.decision_ids),
        "n_tokens": len(generated),
        "tokens_per_s": round(len(generated) / elapsed, 1),
        "ids": generated,
    }


def collect_hidden(model: PrismModel, vocab: Vocab, rows: Sequence[Dict[str, Any]],
                   seqs: Sequence[Sequence[int]], device, torch, autocast):
    """冻结主干，收集决策 token 的探针特征。

    **必须取决策 token 的前一个位置（pos-1）作为预测特征。** v1 取的是 pos
    自身那一行：Transformer 的 residual stream 起点就是 ``embed(ids[pos])``，
    位置 pos 的 hidden 里已经含决策 token 自己的 embedding，线性探针等于
    「照抄输入里的答案」，与模型有没有学到决策毫无关系。实测 v1 在
    C 组 / 打乱组探针宏平均都恰好 1.000，连随机初始化的模型都能做到 ——
    这是标签泄漏，不是能力。

    这里同时收 pos 自身位置作为**泄漏对照**写进报告：它应当接近 1.0，
    而主探针（pos-1）必须明显更低，两者之差才可解释为「模型在预测」。
    """
    net = model.net
    net.eval()
    data: List[Tuple[str, int, Any, Any]] = []
    prev_dist: Dict[str, int] = defaultdict(int)
    prev_ids: set = set()
    with torch.no_grad():
        for row, ids in zip(rows, seqs):
            seq = list(ids)[:net.cfg["max_seq"]]
            if len(seq) < 2:
                continue
            x = torch.tensor([seq], dtype=torch.long, device=device)
            with autocast():
                _, _, h = net(x, return_hidden=True)
            h = h[0].float().cpu()
            for pos, tid in enumerate(seq):
                if pos == 0 or tid not in vocab.decision_ids:
                    continue
                m = DECISION_RE.fullmatch(vocab.text_of(tid))
                p, o = m.group(1), m.group(2)  # type: ignore[union-attr]
                if o not in vocab.point_option_id.get(p, {}):
                    continue
                prev_dist[describe_prev(seq, pos, vocab)] += 1
                prev_ids.add(int(seq[pos - 1]))
                data.append((p, vocab.point_option_id[p][o], h[pos - 1], h[pos]))
    collect_hidden.prev_dist = dict(prev_dist)       # type: ignore[attr-defined]
    collect_hidden.prev_id_count = len(prev_ids)     # type: ignore[attr-defined]
    return data


def describe_prev(seq: Sequence[int], pos: int, vocab: Vocab) -> str:
    """决策 token 前一位置的可读描述，用于报告「特征是否退化为常数」。

    v3.1 修正：初版把所有文本 token 折叠成同一个 ``"<text>"``，导致
    ``len(dist)==1`` 在 scattered 模式下**永远为真** —— 这个哨兵结构上
    不可能报 False。现在带上真实 token 文本 + id，区分不同文本 token。
    注意：这里判断的是「输入 token 是否恒定」，不是「hidden 向量是否恒定」；
    hidden 仍随任务上下文变化，两者不可混为一谈。
    """
    prev = seq[pos - 1]
    if prev in vocab.control_ids:
        return f"{vocab.text_of(prev)}#{prev}"
    if prev < len(vocab.tokens):
        return f"{vocab.tokens[prev]}#{prev}"
    return f"<special>#{prev}"


def train_probe(model: PrismModel, vocab: Vocab, splits, split_seqs, device,
                torch, autocast, epochs: int, seed: int) -> Dict[str, Any]:
    """线性探针：主特征 = 决策 token 前一位置 hidden；另跑一份「自身位置」泄漏对照。

    只在有独立 test 样本的点上报宏平均；每个点单独一个线性头。
    """
    tr = collect_hidden(model, vocab, splits["train"], split_seqs["train"], device, torch, autocast)
    te = collect_hidden(model, vocab, splits["test"], split_seqs["test"], device, torch, autocast)
    torch.manual_seed(seed)

    def fit(feature_idx: int) -> Dict[str, Any]:
        by_tr: Dict[str, List] = defaultdict(list)
        by_te: Dict[str, List] = defaultdict(list)
        for p, y, h_pre, h_self in tr:
            by_tr[p].append((y, (h_pre, h_self)[feature_idx]))
        for p, y, h_pre, h_self in te:
            by_te[p].append((y, (h_pre, h_self)[feature_idx]))
        per_point: Dict[str, Any] = {}
        accs: List[float] = []
        for p in vocab.points:
            n_cls = len(vocab.point_options[p])
            a, b = by_tr.get(p, []), by_te.get(p, [])
            if not a and not b:
                per_point[p] = {"status": "no_samples", "n_classes": n_cls,
                                "random_baseline": round(1 / n_cls, 4)}
                continue
            if not b:
                per_point[p] = {"status": "no_test_samples", "n_train": len(a), "n_test": 0,
                                "n_classes": n_cls, "random_baseline": round(1 / n_cls, 4)}
                continue
            head = torch.nn.Linear(model.dim, n_cls).to(device)
            X = torch.stack([h for _, h in a])
            Y = torch.tensor([y for y, _ in a], dtype=torch.long, device=device)
            opt = torch.optim.AdamW(head.parameters(), lr=1e-3)
            for _ in range(epochs):
                opt.zero_grad()
                loss = torch.nn.functional.cross_entropy(head(X.to(device)), Y)
                loss.backward()
                opt.step()
            Xt = torch.stack([h for _, h in b]).to(device)
            Yt = torch.tensor([y for y, _ in b], dtype=torch.long, device=device)
            with torch.no_grad():
                acc = float((head(Xt).argmax(-1) == Yt).float().mean())
            # 多数类基线：探针如果只是「恒预测训练集里最多的那一类」，准度就是它。
            # 实测 C 组 5/13 = 0.3846 恰好等于多数类，等于零信号；这个基线让
            # 「与随机基线不可区分」进一步收窄成「与常数预测器完全相同」。
            counts = defaultdict(int)
            for y, _ in a:
                counts[y] += 1
            maj_label = max(counts, key=counts.get)
            maj_acc = sum(1 for y, _ in b if y == maj_label) / len(b)
            per_point[p] = {"status": "ok", "n_train": len(a), "n_test": len(b),
                            "accuracy": round(acc, 4), "n_classes": n_cls,
                            "random_baseline": round(1 / n_cls, 4),
                            "majority_baseline": round(maj_acc, 4),
                            "eval_split": "heldout_test"}
            accs.append(acc)
        maj_accs = [v["majority_baseline"] for v in per_point.values()
                    if v.get("status") == "ok"]
        return {"per_point": per_point,
                "macro_accuracy": round(sum(accs) / len(accs), 4) if accs else None,
                "macro_majority_baseline": round(sum(maj_accs) / len(maj_accs), 4)
                                            if maj_accs else None,
                "points_with_test": sorted(p for p, v in per_point.items()
                                           if v.get("status") == "ok")}

    main = fit(0)       # pos-1：不含标签本身，是真正的预测特征
    leak = fit(1)       # pos：标签写在输入里，用作泄漏对照
    covered = main["points_with_test"]
    # v3.2：判定「特征是否退化」必须看 **hidden 向量本身**，不能看输入 token。
    # 本机实测：fixed 模式下 13/13 决策 token 的 pos-1 都是同一个 </TASK>，
    # 但对应 hidden 各维 std 均值 0.60、两两 L2 距离均值 11.65、有效秩 4/13 ——
    # token 恒定完全不代表特征恒定。v3.1 用 token id 种类数当门禁，拦错了对象。
    prev_dist = getattr(collect_hidden, "prev_dist", {}) or {}
    prev_id_count = getattr(collect_hidden, "prev_id_count", None)
    feats = [h_pre for _, _, h_pre, _ in tr] if tr else []
    feature_std = None
    if len(feats) >= 2:
        stacked = torch.stack(feats).float()
        feature_std = round(float(stacked.std(0).mean()), 6)
    const_feature = bool(feature_std is not None and feature_std < 1e-6)
    return {
        **main,
        "feature_position": "pos-1（决策 token 前一位置，不含标签本身）",
        "feature_prev_token_distribution": prev_dist,
        "feature_prev_token_distinct_ids": prev_id_count,
        "feature_hidden_std": feature_std,
        "feature_is_constant": const_feature,
        "self_position_control": {
            "feature_position": "pos（决策 token 自身位置，标签写在输入里的泄漏对照）",
            "macro_accuracy": leak["macro_accuracy"],
            "per_point": {p: v.get("accuracy") for p, v in leak["per_point"].items()},
        },
        "params": sum(model.dim * len(vocab.point_options[p]) + len(vocab.point_options[p])
                      for p in covered),
        "n_train_rows": len(tr), "n_test_rows": len(te),
    }


def train_probe_rival(model: PrismModel, vocab: Vocab, splits, split_seqs, device,
                      torch, autocast, epochs: int, seed: int) -> Dict[str, Any]:
    """A' 组：冻结主干 + **与探针完全相同的 pos-1 特征** + 非线性 MLP 头。

    v2 拿 579 参数的线性探针去比 390419 参数的 A 组文本分类器，参数量不对等。
    A' 与主探针同特征、同 train/test，只把线性头换成 MLP；若 A' 也明显更准，
    说明差距来自「特征不够 + 线性不可分」，而不是「共享表征没编码决策」。
    """
    tr = collect_hidden(model, vocab, splits["train"], split_seqs["train"], device, torch, autocast)
    te = collect_hidden(model, vocab, splits["test"], split_seqs["test"], device, torch, autocast)
    torch.manual_seed(seed + 31337)
    per_point: Dict[str, Any] = {}
    accs: List[float] = []
    for p in vocab.points:
        n_cls = len(vocab.point_options[p])
        a = [(y, h) for pt, y, h, _ in tr if pt == p]
        b = [(y, h) for pt, y, h, _ in te if pt == p]
        if not b:
            per_point[p] = {"status": "no_test_samples", "n_train": len(a), "n_test": 0,
                            "n_classes": n_cls}
            continue
        head = torch.nn.Sequential(
            torch.nn.Linear(model.dim, model.dim), torch.nn.ReLU(),
            torch.nn.Linear(model.dim, n_cls)).to(device)
        X = torch.stack([h for _, h in a]).to(device)
        Y = torch.tensor([y for y, _ in a], dtype=torch.long, device=device)
        opt = torch.optim.AdamW(head.parameters(), lr=1e-3)
        for _ in range(epochs):
            opt.zero_grad()
            loss = torch.nn.functional.cross_entropy(head(X), Y)
            loss.backward()
            opt.step()
        Xt = torch.stack([h for _, h in b]).to(device)
        Yt = torch.tensor([y for y, _ in b], dtype=torch.long, device=device)
        with torch.no_grad():
            acc = float((head(Xt).argmax(-1) == Yt).float().mean())
        per_point[p] = {"status": "ok", "n_train": len(a), "n_test": len(b),
                        "accuracy": round(acc, 4), "n_classes": n_cls,
                        "eval_split": "heldout_test"}
        accs.append(acc)
    return {"per_point": per_point,
            "macro_accuracy": round(sum(accs) / len(accs), 4) if accs else None,
            "points_with_test": sorted(p for p, v in per_point.items() if v.get("status") == "ok"),
            "params": sum(model.dim * model.dim + model.dim +
                          model.dim * len(vocab.point_options[p]) + len(vocab.point_options[p])
                          for p in per_point if per_point[p].get("status") == "ok"),
            "feature_position": "pos-1（与 C 组主探针完全同特征）",
            "note": "与 C 探针同特征、同切分，只把线性头换成 MLP；用于判断差距是否来自线性可分性"}


def train_decision_baseline(vocab: Vocab, splits, split_seqs, device, torch,
                            epochs: int, seed: int) -> Dict[str, Any]:
    """A 组：独立轻量决策模型（Embedding+MLP 多任务头），< 1M 参数。"""
    torch.manual_seed(seed)
    H = 128

    class Baseline(torch.nn.Module):
        def __init__(self):
            super().__init__()
            self.emb = torch.nn.Embedding(vocab.vocab_size, H, padding_idx=vocab.pad_id)
            self.fc = torch.nn.Sequential(torch.nn.Linear(H, H), torch.nn.ReLU())
            self.heads = torch.nn.ModuleDict({
                p: torch.nn.Linear(H, len(o)) for p, o in vocab.point_options.items()})

        def forward(self, ids):
            m = (ids != vocab.pad_id).float().unsqueeze(-1)
            h = (self.emb(ids) * m).sum(1) / m.sum(1).clamp(min=1.0)
            h = self.fc(h)
            return {p: head(h) for p, head in self.heads.items()}

    def rows_for(name):
        out = []
        for row, ids in zip(splits[name], split_seqs[name]):
            labels: Dict[str, int] = {}
            for tid in ids:
                if tid in vocab.decision_ids:
                    m = DECISION_RE.fullmatch(vocab.text_of(tid))
                    p, o = m.group(1), m.group(2)  # type: ignore[union-attr]
                    labels[p] = vocab.point_option_id[p][o]
            if labels:
                task = [vocab.structure["<TASK>"]] + vocab.encode_text(row["task"]) + [
                    vocab.structure["</TASK>"]]
                out.append((task, labels))
        return out

    tr, te = rows_for("train"), rows_for("test")
    net = Baseline().to(device)
    params = sum(p.numel() for p in net.parameters())
    opt = torch.optim.AdamW(net.parameters(), lr=3e-3)
    max_len = 256
    for _ in range(epochs):
        for task, labels in tr:
            ids = torch.tensor([task[:max_len]], dtype=torch.long, device=device)
            lg = net(ids)
            loss = sum(torch.nn.functional.cross_entropy(lg[p],
                       torch.tensor([y], dtype=torch.long, device=device))
                       for p, y in labels.items())
            opt.zero_grad()
            loss.backward()
            opt.step()
    per_point: Dict[str, Any] = {}
    accs: List[float] = []
    net.eval()
    for p in vocab.points:
        pts = [(task, y) for task, lab in te for p2, y in lab.items() if p2 == p]
        if not pts:
            per_point[p] = {"status": "no_samples", "random_baseline": round(1 / len(vocab.point_options[p]), 4)}
            continue
        hit = 0
        with torch.no_grad():
            for task, y in pts:
                ids = torch.tensor([task[:max_len]], dtype=torch.long, device=device)
                if int(net(ids)[p].argmax(-1).item()) == y:
                    hit += 1
        acc = hit / len(pts)
        per_point[p] = {"status": "ok", "n_test": len(pts), "accuracy": round(acc, 4),
                        "random_baseline": round(1 / len(vocab.point_options[p]), 4),
                        "eval_split": "heldout_test"}
        accs.append(acc)
    return {"per_point": per_point,
            "macro_accuracy": round(sum(accs) / len(accs), 4) if accs else None,
            "points_with_test": sorted(p for p, v in per_point.items() if v.get("status") == "ok"),
            "params": params, "n_train_rows": len(tr), "n_test_rows": len(te)}


# ===========================================================================
# 4. 判定与报告
# ===========================================================================
def judge(metrics: Dict[str, Any], cfg: Dict[str, Any]) -> Dict[str, Any]:
    """四条判据 + v3 门禁。

    门禁只封 **①（探针）** 与因差距不足而封的 **②（生成质量）**：这两条依赖
    决策标签覆盖与样本量。③④ 不依赖决策标签，是**有效测量**，该 pass 就 pass、
    该 fail 就 fail。门禁命中时整体 verdict 降为 incomplete（不再报 fail），
    因为「方案是否通」这个综合结论仍无判别力 —— v2 的 fail 强度超过了证据等级。
    """
    checks: List[Dict[str, Any]] = []

    def add(name, ok: Optional[bool], detail: str):
        checks.append({"criterion": name,
                       "result": "unknown" if ok is None else ("pass" if ok else "fail"),
                       "detail": detail})

    c = metrics["C"]["probe"]
    a = metrics["A"]["macro_accuracy"]
    covered = c.get("points_with_test") or []
    rand_base = (sum(c["per_point"][p]["random_baseline"] for p in covered) /
                 max(len(covered), 1)) if covered else 0.5

    # ---- v3 门禁（P0）：先算清楚这轮有没有资格做判定 ----
    cov = metrics.get("coverage") or {}
    blockers: List[str] = []
    if len(covered) < N_DECISION_POINTS:
        blockers.append(f"决策点只覆盖 {len(covered)}/{N_DECISION_POINTS} 个（{covered}）")
    if (c.get("n_test_rows") or 0) < MIN_PROBE_TEST_ROWS:
        blockers.append(f"探针 test 样本 {c.get('n_test_rows')} 条 < {MIN_PROBE_TEST_ROWS}")
    overlap = cov.get("split_diagnostics", {}).get("train_test_template_overlap")
    if overlap:
        blockers.append(f"train/test 模板簇重合 {overlap} 个（A 组可能是记忆而非泛化）")
    if cov.get("validation_codes_seen") and not cov.get("has_err_validation"):
        blockers.append("验证 token 只有 PASS，8 类 <V:ERR=...> 无正样本")
    if c.get("feature_is_constant"):
        blockers.append(f"pos-1 的 hidden 向量退化（各维 std={c.get('feature_hidden_std')} ≈ 0）")
    gated = bool(blockers)

    # ---- ① 探针准确率 ----
    maj = c.get("macro_majority_baseline")
    if gated:
        add("① 探针准确率 ≥ A 组外挂分类器", None,
            "门禁未通过，判据不可测：" + "；".join(blockers))
    elif a is None or c["macro_accuracy"] is None:
        add("① 探针准确率 ≥ A 组外挂分类器", None, "C 或 A 组宏平均缺数据（决策点无 test 样本）")
    elif maj is not None and c["macro_accuracy"] <= maj:
        # v3.2：C 若不高于「恒预测训练集多数类」，就是常数预测器，连随机基线
        # 的比较都没意义。实测 0.3846 恰等于多数类 5/13 = 0.3846。
        add("① 探针准确率 ≥ A 组外挂分类器", None,
            f"C={c['macro_accuracy']:.3f} ≤ 多数类基线 {maj:.3f}"
            f"（A={a:.3f}）；探针等价于恒预测多数类，零信号，不是通过")
    elif c["macro_accuracy"] < rand_base + 0.10:
        add("① 探针准确率 ≥ A 组外挂分类器", None,
            f"C={c['macro_accuracy']:.3f} vs A={a:.3f}，但 C 未高于随机基线 "
            f"{rand_base:.3f}+0.10，本轮探针无判别力（不是通过）")
    elif ((c["macro_accuracy"] >= CEILING_ACC or a >= CEILING_ACC)
          and (c.get("n_test_rows") or 0) < MIN_DECISIVE_SAMPLES):
        # v3：天花板保护放宽到任一组接近满分且样本不足（v2 只护双 ≥0.99，
        # 结果「C 考 0.714 判 fail、C 考 1.000 反而记 unknown」逻辑倒挂）
        add("① 探针准确率 ≥ A 组外挂分类器", None,
            f"C={c['macro_accuracy']:.3f} vs A={a:.3f}，任一组 ≥{CEILING_ACC} 且 "
            f"test <{MIN_DECISIVE_SAMPLES}（天花板效应），该比较无判别力")
    else:
        add("① 探针准确率 ≥ A 组外挂分类器", c["macro_accuracy"] >= a,
            f"C={c['macro_accuracy']:.3f} vs A={a:.3f}；随机基线 {rand_base:.3f}")

    # ---- ② 一次通过率（拆成「JSON 代理」与「真实口径」两件事） ----
    cj = metrics["C"]["gen"]["json"]
    bj = metrics["B"]["gen"]["json"] if "B" in metrics else None
    gap = abs(cj.get("exact", 0) - (bj or {}).get("exact", 0))
    if bj is None or cj["n"] == 0:
        add("② 一次通过率 ≥ B 组", None, "缺 B 组或 JSON 代理样本")
    elif cj["exact_rate"] == 0 and bj["exact_rate"] == 0:
        add("② 一次通过率 ≥ B 组", None,
            f"C/B 两组 JSON 精确匹配均为 0（n={cj['n']}），本轮生成能力不足以产生判别力")
    elif cj["n"] < MIN_DECISIVE_SAMPLES:
        add("② 一次通过率 ≥ B 组", None,
            f"JSON 代理样本仅 {cj['n']} 条（要求 ≥{MIN_DECISIVE_SAMPLES}）")
    elif gap < MIN_DECISIVE_GAP:
        # v3：堵住 8/42 vs 7/42 这种「差 1 条就判 pass」的擦边
        add("② 一次通过率 ≥ B 组（JSON 精确匹配代理）", None,
            f"C={cj['exact_rate']:.3f} vs B={bj['exact_rate']:.3f}，"
            f"精确匹配只差 {gap} 条（要求 ≥{MIN_DECISIVE_GAP}），统计上无判别力")
    else:
        add("② 一次通过率 ≥ B 组（JSON 精确匹配代理）", cj["exact_rate"] >= bj["exact_rate"],
            f"C={cj['exact_rate']:.3f} vs B={bj['exact_rate']:.3f}（差 {gap} 条）"
            "；注意：这是 JSON 代理，不是判据原文的 light ai check --run 一次通过率")
    # 真实口径不列为第五条「判据」（§7.3 只有四条），而是写进 caveats，
    # 否则 OpenI 上永远有一条 unknown、pass 不可达。这里只把口径差异记进代理的 detail。
    true_pass_rate_note = ("真实一次通过率需 light ai check --json --run，OpenI 无光明解释器，"
                           "本环境不可测；光明代码类样本亦不并入 JSON 代理")

    # ---- ③ 结构合法率（v3：截断计入全分母） ----
    fr = metrics["C"]["gen"]["free"]
    sr = fr.get("structure_rate_all")
    n_all = fr.get("n_all", 0)
    n_trunc = fr.get("n_truncated", 0)
    if n_all < MIN_DECISIVE_SAMPLES:
        add("③ 无约束结构合法率 ≥ 95%", None,
            f"生成样本仅 {n_all} 条（要求 ≥{MIN_DECISIVE_SAMPLES}）")
    else:
        add("③ 无约束结构合法率 ≥ 95%", None if sr is None else sr >= STRUCTURE_MIN,
            f"{sr if sr is not None else 'unknown'}（全 {n_all} 条分母，"
            f"其中 {n_trunc} 条截断按失败计入；约束解码结果不计入）")

    # ---- ④ 密度/速度 ----
    dens = metrics["C"]["gen"]["decision_density"]
    drop = metrics["C"]["gen"]["speed_drop_vs_B"]
    if drop is None:
        add("④ 决策密度 ≤ 2% 且速度下降 ≤ 15%", None,
            f"密度={dens}（已测）但缺 B 组速度对照，整条判据不可判定")
    else:
        add("④ 决策密度 ≤ 2% 且速度下降 ≤ 15%", dens <= DENSITY_MAX and drop <= SPEED_DROP_MAX,
            f"密度={dens:.4f}（≤{DENSITY_MAX}），速度下降={drop:.3f}（≤{SPEED_DROP_MAX}）")

    fails = [x for x in checks if x["result"] == "fail"]
    unknowns = [x for x in checks if x["result"] == "unknown"]
    verdict = "pass" if not fails and not unknowns else ("fail" if fails else "incomplete")

    # ---- 反向哨兵 ----
    shuf = metrics.get("shuffle", {}).get("probe", {}).get("macro_accuracy")
    leak_threshold = round(max(0.70, rand_base + 0.25), 4)
    leakage = shuf is not None and shuf > leak_threshold
    if leakage:
        verdict = "invalid"
        checks.append({"criterion": "反向哨兵（标签打乱）", "result": "fail",
                       "detail": f"打乱组探针宏平均 {shuf:.3f} > 阈值 {leak_threshold}"
                                 f"（随机基线 {rand_base:.3f} + 0.25）。请核对 C.probe.feature_position"
                                 " 与 self_position_control 对照"})

    # ---- 证据等级 ----
    caveats: List[str] = []
    if cfg["decision_policy"] == "rule":
        caveats.append("决策标签为规则派生的合成标签（--decision-policy rule），只能验证机制")
        evidence = "mechanism_only"
    else:
        covered_points = c["points_with_test"]
        evidence = "real_labels" if len(covered_points) == N_DECISION_POINTS else "partial_coverage"
        if evidence != "real_labels":
            caveats.append(f"真实决策标签只覆盖 {len(covered_points)}/7 个决策点（{covered_points}）")
    caveats.append(true_pass_rate_note + "（记为口径限制，不单独占一条判据）")
    caveats.append("A/B 组是本次实验内的消融对照，不是方案书里已部署的外部系统")
    caveats.append("C/B 组同 epoch、同 batch-size，但 C 组每条序列多出决策/验证 token；"
                   "比较的是结果指标，不是等 token 预算下的严格对照")
    caveats.append(f"判据 ②③ 要求 ≥{MIN_DECISIVE_SAMPLES} 条评估样本，且 ② 要求差距 ≥"
                   f"{MIN_DECISIVE_GAP} 条；不足记 unknown")
    caveats.append("探针主特征取决策 token 前一位置（pos-1）；自身位置的探针只作泄漏对照，"
                   "不参与判据（v1 误用自身位置，导致 C 组与打乱组探针都是 1.000）")

    # ---- 门禁总闸：证据不足时不许升级为 fail / pass ----
    if gated and verdict in ("fail", "pass"):
        verdict = "incomplete"
    if gated:
        caveats.append("v3 门禁命中：" + "；".join(blockers)
                       + "。①（探针）与差距不足的 ② 因此不可测；③④ 不依赖决策标签，"
                         "仍为有效测量（可能 pass 也可能 fail）。综合结论「方案通不通」"
                         "无判别力，整体记 incomplete，不升级为 fail/pass")
    if verdict == "pass" and evidence != "real_labels":
        verdict = "incomplete"
        caveats.append("证据等级不足，四条判据即使全绿也不升级为 pass")

    return {
        "verdict": verdict, "evidence_level": evidence, "checks": checks,
        "gated": gated, "gate_blockers": blockers,
        "shuffle_probe_macro_accuracy": shuf, "leak_threshold": leak_threshold,
        "leakage_suspected": leakage,
        "caveats": caveats,
        "next_step": {
            "pass": "进入阶段二「序列内协同」训练",
            "fail": "四条判据中至少一条实测不达标，按 docs/探针实验设计.md §6 固定顺序调参后重跑",
            "incomplete": ("先补齐门禁条件：7 个决策点各 ≥30 真实/机制标注正样本、"
                           "按模板簇分组切分零重合、验证 ERR 类覆盖。"
                           "注意 C 探针已与「多数类基线」持平（等价于恒预测多数类），"
                           "说明当前 35 条决策样本不足以让探针学到任何东西——"
                           "该补的是决策样本数量与难度，不是调超参。"
                           "若用 --decision-position scattered，v3.2 已保证推理 prompt "
                           "与训练同窗口；若仍看到 ③ 异常低，先核对这一点"),
            "invalid": "先核对 C.probe.feature_position 是否为 pos-1、self_position_control 是否显著更高；"
                       "再查 train/test 是否混入同一样本，修复后重跑",
        }[verdict],
    }


def render_report(metrics: Dict[str, Any], cfg: Dict[str, Any], env: Dict[str, Any],
                  stats: Dict[str, Any], verdict: Dict[str, Any]) -> str:
    L: List[str] = []
    A = L.append
    A("# LightPrism · OpenI/V100 思路验证报告")
    A("")
    A(f"- 运行时间：{time.strftime('%Y-%m-%d %H:%M:%S')}")
    A(f"- 环境：Python {env.get('python')} / torch {env.get('torch')} / {env.get('gpu', 'CPU')} "
      f"(SM {env.get('compute_capability', '-')}) / {env.get('amp', metrics.get('dtype'))}")
    A(f"- 词表：{stats['vocab_size']} id（2900 实词 + PAD/UNK），"
      f"控制区间 [{stats['ctrl_start']}, {stats['ctrl_end']})，"
      f"UNK {stats['unk_ratio']:.4%}（训练序列 token 口径，"
      "与词表报告的字符级 0.1997% 不可直接比较）")
    A(f"- 数据：{stats['samples']} 条，train/val/test = "
      f"{stats['splits']['train']}/{stats['splits']['val']}/{stats['splits']['test']}")
    A(f"- 决策策略：`{cfg['decision_policy']}`；模型档 `{cfg['preset']}`"
      f"（{metrics.get('params', 0):,} 参数）")
    cp = metrics["C"]["probe"]
    A(f"- 探针特征：`{cp.get('feature_position', 'pos-1')}`；"
      f"泄漏对照（决策 token 自身位置）宏平均 = "
      f"{cp.get('self_position_control', {}).get('macro_accuracy', '—')}"
      "（该对照高属预期，不参与判据）")
    A(f"- 前一位置分布：`{cp.get('feature_prev_token_distribution', {})}`；"
      f"不同 token id 种类 = `{cp.get('feature_prev_token_distinct_ids', '—')}`。")
    A(f"- 探针特征 hidden 各维 std 均值 = `{cp.get('feature_hidden_std', '—')}`，"
      f"特征退化 = `{cp.get('feature_is_constant', '—')}`。"
      "**判定看 hidden 方差，不看 token id**：token 恒定不等于特征恒定"
      "（实测 fixed 模式下 13/13 是 `</TASK>`，但 hidden std=0.60、两两 L2=11.65）")
    A(f"- 多数类基线 = `{cp.get('macro_majority_baseline', '—')}`："
      "C 若不超过它，等于「恒预测训练集多数类」，零信号")
    cov = metrics.get("coverage") or {}
    A(f"- 切分：`group_split={cov.get('split_diagnostics', {}).get('group_split')}`，"
      f"模板簇 {cov.get('split_diagnostics', {}).get('n_clusters')} 个，"
      f"train/test 重合 {cov.get('split_diagnostics', {}).get('train_test_template_overlap')} 个")
    A(f"- 决策点覆盖：`{cov.get('points_with_test_labels', [])}` "
      f"（{cov.get('n_points_with_test_labels', '—')}/7），"
      f"test 决策行数 {cov.get('n_test_decision_rows', '—')}；"
      f"验证码 `{cov.get('validation_codes_seen', [])}`，含 ERR 类 = "
      f"`{cov.get('has_err_validation', '—')}`")
    A("")
    A("## 先看结论")
    A("")
    A(f"**verdict = `{verdict['verdict']}`**，证据等级 `{verdict['evidence_level']}`，"
      f"门禁命中 = `{verdict.get('gated', False)}`。")
    A(f"{verdict['next_step']}。")
    if verdict.get("gate_blockers"):
        A("")
        A("**门禁拦截项（这些不补齐，四条判据都不可测）：**")
        for b in verdict["gate_blockers"]:
            A(f"- {b}")
    A("")
    for c in verdict["checks"]:
        A(f"- `{c['result']}` **{c['criterion']}** — {c['detail']}")
    A("")
    A("> 约束解码的结构合法率是外部状态机强制的，不能当模型能力（假绿）。")
    A("> 判据 ③ 用**无约束**贪心解码，且**截断生成按失败计入全分母**（v2 把它们从分母里剔除了）。")
    A("")
    A("## 诚实边界（务必随报告一起读）")
    A("")
    for x in verdict["caveats"]:
        A(f"- {x}")
    A("")
    A("## 三组对照")
    A("")
    A("| 组 | 做法 | 探针宏平均 | JSON 精确匹配 | 无约束结构合法率 | tokens/s |")
    A("|---|---|---:|---:|---:|---:|")
    for tag, desc in (("C", "统一序列（决策/代码/验证共享词表与损失）"),
                      ("B", "消融：去掉决策与验证 token，纯生成"),
                      ("A", "外挂轻量决策分类器（< 1M 参数）"),
                      ("shuffle", "负对照：决策标签同点内打乱后重训")):
        if tag not in metrics:
            continue
        g = metrics[tag]
        probe = (g["probe"]["macro_accuracy"] if "probe" in g
                 else g.get("macro_accuracy"))
        gen = g.get("gen", {})
        j = gen.get("json", {})
        free = gen.get("free", {})
        A(f"| {tag} | {desc} | {probe if probe is not None else '—'} | "
          f"{j.get('exact_rate', '—')} | {free.get('structure_rate', '—')} | "
          f"{free.get('tokens_per_s', '—')} |")
    A("")
    A(f"反向哨兵：打乱组探针宏平均 = {verdict['shuffle_probe_macro_accuracy']}，"
      f"泄漏阈值 = {verdict['leak_threshold']}（随机基线 + 0.25，不低于 0.70），"
      f"泄漏判定 = `{verdict['leakage_suspected']}`。")
    rival = metrics.get("A_rival")
    if rival:
        A("")
        A(f"A' 对等对照（冻结主干 + 同 pos-1 特征 + MLP，{rival.get('params', '—')} 参数）："
          f"宏平均 = {rival.get('macro_accuracy', '—')}，覆盖 {rival.get('points_with_test', [])}。"
          "若 A' 也明显更准，说明 C 的差距来自「特征不够 / 线性不可分」，而非共享表征没编码决策。")
    geom = metrics.get("embedding_geometry")
    if geom:
        A("")
        A(f"阶段一几何检查点（方案 §7）：{geom['n_decision_tokens_seen_as_input']}/"
          f"{geom['n_decision_tokens']} 个决策 token **曾作为输入**出现，"
          f"{geom['n_decision_tokens_never_seen_as_input']} 个从未作为输入出现"
          f"（tied_embedding={geom['tied_embedding']}）。")
        seen = geom.get("cosine_dec_vs_text_seen_as_input", {})
        allc = geom.get("cosine_dec_vs_text_all", {})
        A(f"  决策/文本嵌入余弦：曾作为输入子集 mean={seen.get('mean', '—')}"
          f"（n={seen.get('n', 0)}），全体 mean={allc.get('mean', '—')}、"
          f"p50={allc.get('p50', '—')}。")
        A(f"  {geom['note']}")
        if geom["never_seen_as_input_examples"]:
            A(f"  从未作为输入的样例：`{geom['never_seen_as_input_examples']}`。")
    gn = metrics.get("grad_norm_summary")
    if gn and gn.get("status") != "no_data":
        A(f"梯度范数（§8.6）：控制/文本行比值 mean={gn['control_over_text_ratio_mean']}、"
          f"p50={gn['control_over_text_ratio_p50']}、max={gn['control_over_text_ratio_max']}"
          f"（{gn['n_steps']} 步）。持续显著 >1 说明损失权重失衡。")
    A("")
    A("## 决策点逐点明细（C 组探针）")
    A("")
    A("| 决策点 | C 探针 | A 组 | 打乱组 | 随机基线 | 多数类基线 | n_train / n_test | 状态 |")
    A("|---|---:|---:|---:|---:|---:|---|---|")
    for p in stats["points"]:
        c = metrics["C"]["probe"]["per_point"].get(p, {})
        a = metrics["A"]["per_point"].get(p, {}) if "A" in metrics else {}
        s = metrics.get("shuffle", {}).get("probe", {}).get("per_point", {}).get(p, {})
        A(f"| {p} | {c.get('accuracy', '—')} | {a.get('accuracy', '—')} | "
          f"{s.get('accuracy', '—')} | {c.get('random_baseline', '—')} | "
          f"{c.get('majority_baseline', '—')} | "
          f"{c.get('n_train', '—')}/{c.get('n_test', '—')} | {c.get('status', '—')} |")
    A("")
    A("## 训练与数据口径")
    A("")
    A(f"- 决策 token 密度（训练序列 id 口径）：{stats['decision_density']:.4%}"
      f"（上限 {DENSITY_MAX:.0%}），结构/验证 token 数 "
      f"{stats['structure_tokens']} / {stats['validation_tokens']}")
    A(f"- 判据 ④ 用的是**生成序列**决策密度 "
      f"{metrics['C']['gen']['decision_density']:.4%}；与训练序列口径不同，不可混用")
    A(f"- 训练序列长度：均值 {stats['mean_len']}，最大 {stats['max_len']}，"
      f"seq_len={cfg['seq_len']}，被截断样本 {stats['over_seq_len_samples']} 条")
    A(f"- 验证 token 实际出现码：{stats['validation_codes_seen']}")
    A(f"- 数据 SHA-256：见 config.json。词表与样本内嵌于脚本，可用 `--dump-data DIR` 导出复核。")
    A(f"- 生成评估：{cfg['eval_gen_samples']} 条 test 样本，无约束 / 约束各跑一遍；"
      f"判据 ②③ 的最小样本量 {MIN_DECISIVE_SAMPLES}，不足记 unknown")
    A("- 生成样例见 `generated_samples.jsonl`（含模型吐错的原始序列，未做美化）。")
    A("")
    return "\n".join(L) + "\n"


# ===========================================================================
# 5. 主流程
# ===========================================================================
def build_arg_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(
        prog="train_openi.py",
        description="LightPrism 单文件训练 + 思路验证（OpenI / V100）",
        formatter_class=argparse.ArgumentDefaultsHelpFormatter)
    p.add_argument("--out-dir", default="", help="输出目录，默认 ./lightprism_out")
    p.add_argument("--data-dir", default="", help="外部数据目录（覆盖内嵌词表/样本）")
    p.add_argument("--dump-data", default="", help="把内嵌数据解出到该目录后退出")
    p.add_argument("--preset", choices=sorted(PRESETS), default="demo")
    p.add_argument("--epochs", type=int, default=30)
    p.add_argument("--batch-size", type=int, default=16)
    p.add_argument("--seq-len", type=int, default=768,
                   help="定长批次长度；实测最长样本 662 token，低于它会截断")
    p.add_argument("--lr", type=float, default=3e-4)
    p.add_argument("--weight-decay", type=float, default=0.1)
    p.add_argument("--warmup-ratio", type=float, default=0.05)
    p.add_argument("--min-lr-ratio", type=float, default=0.1)
    p.add_argument("--grad-clip", type=float, default=1.0)
    p.add_argument("--control-weight", type=float, default=1.0,
                   help="阶段一按方案不加权；>1 相当阶段二的加权旋钮")
    p.add_argument("--decision-policy", choices=("real", "rule", "off"), default="real")
    p.add_argument("--group-split", action="store_true",
                   help="按「类别+归一化 task 模板簇」分组切分，避免同模板变体跨 train/test（v3 默认建议开）")
    p.add_argument("--decision-position", choices=("fixed", "scattered"), default="fixed",
                   help="scattered 把决策 token 随机插入任务文本后缀之后，使 pos-1 特征不再恒为 </TASK>")
    p.add_argument("--a-group-rival", action="store_true",
                   help="跑 A' 对等对照：冻结主干 + 同 pos-1 特征 + MLP 头")
    p.add_argument("--min-decisive-gap", type=int, default=MIN_DECISIVE_GAP,
                   help="判据 ② C/B 精确匹配相差少于该条数时记 unknown")
    p.add_argument("--seed", type=int, default=0)
    p.add_argument("--log-every", type=int, default=25)
    p.add_argument("--eval-gen-samples", type=int, default=52,
                   help="生成评估取多少条 test；判据 ②③ 要求 ≥30，默认跑满 52 条 test")
    p.add_argument("--max-new-tokens", type=int, default=384,
                   help="生成上限；实测生成段 p95=330，v2 的 160 会截掉约 14%% 样本（v3 提到 384）")
    p.add_argument("--probe-epochs", type=int, default=120)
    p.add_argument("--baseline-epochs", type=int, default=12)
    p.add_argument("--no-shuffle-control", action="store_true")
    p.add_argument("--skip-b-group", action="store_true")
    p.add_argument("--amp", choices=("auto", "fp16", "bf16", "off"), default="auto")
    p.add_argument("--device", default="", help="cuda / cpu / cuda:0；默认自动")
    p.add_argument("--c2net", action="store_true", help="OpenI: 用 c2net prepare() 的 output_path")
    p.add_argument("--c2net-upload", action="store_true", help="OpenI: 结束时 upload_output()")
    p.add_argument("--self-check", action="store_true", help="纯标准库自检，不需要 torch")
    p.add_argument("--smoke", action="store_true", help="最小步数先验环境")
    p.add_argument("--steps-limit", type=int, default=0, help="每 epoch 最多多少个 batch（0=不限）")
    p.add_argument("--no-report-to-repo", action="store_true",
                   help="不把 reports/探针实验_<日期>.{md,json} 写进仓库目录（§8 产出物）")
    return p


def self_check(payload: Dict[str, Any], vocab: Vocab, rows, splits, cfg) -> int:
    """不需要 torch：把数据/词表/序列/切分/权重/batch 全跑一遍并打印。"""
    print("== self-check ==")
    print(f"vocab: size={vocab.vocab_size} control=[{vocab.ctrl_start},{vocab.ctrl_end}) "
          f"L0={len(vocab.l0_set)} points={vocab.points}")
    seqs = {}
    for name in ("train", "val", "test"):
        seqs[name] = [build_ids(r, vocab, cfg["decision_policy"],
                                decision_position=cfg["decision_position"],
                                position_rng=random.Random(cfg["seed"] + i))[0]
                      for i, r in enumerate(splits[name])]
        print(f"split {name}: {len(seqs[name])} 条")
    st = dataset_stats(seqs["train"], vocab)
    print("train stats:", json.dumps(st, ensure_ascii=False))
    assert st["tokens"] > 0 and st["decision_density_ok"], "决策密度超限"
    assert st["unk_ratio"] < 0.05, f"UNK 率异常 {st['unk_ratio']}"
    # 控制 token 必须连续且 id 唯一
    assert sorted(vocab.control_ids) == list(range(vocab.ctrl_start, vocab.ctrl_end))
    assert len(set(vocab.control_ids)) == len(vocab.control_ids)
    # 训练序列在 </TASK> 之后的「生成段」必须能通过结构复核
    end_task = vocab.structure["</TASK>"]
    for s in seqs["train"][:20]:
        tail = list(s[s.index(end_task) + 1:])
        ok, probs = check_structure(tail, vocab, True)
        assert ok, f"训练序列自身结构不合法: {probs}"
    # batch 形状与 pad 权重
    b = make_batches(seqs["train"], vocab, cfg["seq_len"], min(4, cfg["batch_size"]),
                     cfg["control_weight"], random.Random(cfg["seed"]), limit=1)[0]
    assert all(len(r) == cfg["seq_len"] for r in b["x"])
    assert all(len(r) == cfg["seq_len"] for r in b["y"])
    assert all(w == 0.0 for r, q in zip(b["w"], b["y"]) for w, t in zip(r, q) if t == vocab.pad_id)
    print(f"batch: x={len(b['x'])}x{len(b['x'][0])} pad-weight OK")
    # 编解码往返
    row = rows[0]
    ids, labels = build_ids(row, vocab, "rule")
    decoded = vocab.decode_text([i for i in ids if i < vocab.ctrl_start])
    assert row["task"][:10] in decoded, "任务文本编解码往返失败"
    print(f"roundtrip OK; rule labels: {labels}")
    # v3：打印门禁诊断，纯标准库即可复核
    cov = label_coverage(splits, seqs, vocab)
    cov["split_diagnostics"] = cfg.get("split_diagnostics", {})
    print("v3 coverage:", json.dumps(cov, ensure_ascii=False))
    print("v3 split_diagnostics:", json.dumps(cov["split_diagnostics"], ensure_ascii=False))
    print("== self-check PASS ==")
    return 0


def main(argv: Optional[Sequence[str]] = None) -> int:
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    args = build_arg_parser().parse_args(argv)
    if args.smoke:
        args.epochs = 1
        args.steps_limit = 2
        args.eval_gen_samples = 2
        args.max_new_tokens = 24
        args.probe_epochs = 5
        args.baseline_epochs = 2
        args.no_shuffle_control = True
        args.log_every = 1

    payload = _load_payload(args)
    if args.dump_data:
        d = Path(args.dump_data)
        d.mkdir(parents=True, exist_ok=True)
        (d / "vocab_4096.json").write_text(
            json.dumps(payload["vocab"], ensure_ascii=False, indent=2), encoding="utf-8")
        for k in ("json_tasks", "code_tasks"):
            (d / (k + ".jsonl")).write_text(payload[k], encoding="utf-8")
        print(f"已导出内嵌数据到 {d.resolve()}")
        return 0

    vocab = Vocab(payload["vocab"])
    rows = load_samples(payload)
    # T-0494：限量已在 load_samples 内完成（sha256 确定性），诊断从 meta 取
    budget = dict((payload.get("meta") or {}).get("decision_budget") or {})
    cfg = {
        "schema": SCHEMA, "preset": args.preset, "epochs": args.epochs,
        "batch_size": args.batch_size, "seq_len": args.seq_len,
        "lr": args.lr, "weight_decay": args.weight_decay, "warmup_ratio": args.warmup_ratio,
        "min_lr_ratio": args.min_lr_ratio, "grad_clip": args.grad_clip,
        "control_weight": args.control_weight, "decision_policy": args.decision_policy,
        "group_split": args.group_split, "decision_position": args.decision_position,
        "a_group_rival": args.a_group_rival, "min_decisive_gap": args.min_decisive_gap,
        "no_report_to_repo": args.no_report_to_repo,
        "seed": args.seed, "log_every": args.log_every, "amp": args.amp,
        "eval_gen_samples": args.eval_gen_samples, "max_new_tokens": args.max_new_tokens,
        "probe_epochs": args.probe_epochs, "baseline_epochs": args.baseline_epochs,
        "shuffle_control": not args.no_shuffle_control, "b_group": not args.skip_b_group,
        "steps_limit": args.steps_limit or None, "smoke": args.smoke,
        "epoch_limit": None, "decision_budget": budget,
    }
    split_diag: Dict[str, Any] = {}
    splits = stratified_split(rows, args.seed, group_split=args.group_split,
                              coverage=split_diag)
    cfg["split_diagnostics"] = split_diag

    if args.self_check:
        return self_check(payload, vocab, rows, splits, cfg)

    import torch
    device = torch.device(args.device or ("cuda" if torch.cuda.is_available() else "cpu"))
    autocast, scaler, dtype = amp_helpers(device, torch, args.amp)
    env = env_report(device)
    env["amp"] = dtype
    print("== 环境 ==", json.dumps(env, ensure_ascii=False))

    # 输出目录：--out-dir > c2net output_path > cwd/lightprism_out
    c2net_upload = None
    out_dir = Path(args.out_dir) if args.out_dir else Path.cwd() / "lightprism_out"
    if args.c2net:
        try:
            from c2net.context import prepare, upload_output  # type: ignore
            ctx = prepare()
            out_dir = Path(getattr(ctx, "output_path", None) or out_dir)
            c2net_upload = upload_output
            print(f"[openi] c2net output_path = {out_dir}")
        except Exception as exc:  # c2net 缺失/未授权都不该让训练失败
            print(f"[openi] c2net 不可用，改用本地目录：{exc}")
    out_dir.mkdir(parents=True, exist_ok=True)
    (out_dir / "checkpoints").mkdir(exist_ok=True)
    (out_dir / "train_log.jsonl").unlink(missing_ok=True)   # 不混上次运行的日志

    # ---- 序列与 batch ----
    def seqs_for(policy, shuffle_seed=None):
        rng = random.Random(shuffle_seed) if shuffle_seed is not None else None
        out = {}
        for name in ("train", "val", "test"):
            out[name] = [build_ids(r, vocab, policy, rng,
                                   decision_position=args.decision_position,
                                   position_rng=random.Random(args.seed + 5000 + i))[0]
                         for i, r in enumerate(splits[name])]
        return out

    c_seqs = seqs_for(args.decision_policy)
    b_seqs = {k: [strip_controls(s, vocab) for s in v] for k, v in c_seqs.items()}
    shuf_seqs = seqs_for(args.decision_policy, shuffle_seed=args.seed + 991) \
        if cfg["shuffle_control"] else None

    # v3 门禁诊断：纯标准库，训练前就能算出这轮有没有资格判定
    coverage = label_coverage(splits, c_seqs, vocab)
    coverage["split_diagnostics"] = split_diag
    print("== v3 覆盖诊断 ==", json.dumps(coverage, ensure_ascii=False))

    st = dataset_stats(c_seqs["train"], vocab)
    st["over_seq_len_samples"] = sum(1 for s in c_seqs["train"] if len(s) > args.seq_len + 1)
    st.update({"vocab_size": vocab.vocab_size, "ctrl_start": vocab.ctrl_start,
               "ctrl_end": vocab.ctrl_end, "points": vocab.points,
               "samples": len(rows),
               "splits": {k: len(v) for k, v in splits.items()},
               "payload": payload["meta"]})
    cfg.update({"data_stats": st, "env": env})
    (out_dir / "config.json").write_text(
        json.dumps(cfg, ensure_ascii=False, indent=2), encoding="utf-8")
    print("== 数据 ==", json.dumps(st, ensure_ascii=False))

    def batches_for(seqs, seed):
        all_ep = []
        for ep in range(args.epochs):
            all_ep.append(make_batches(
                seqs["train"], vocab, args.seq_len, args.batch_size,
                args.control_weight, random.Random(seed + ep), cfg["steps_limit"]))
        vb = make_batches(seqs["val"], vocab, args.seq_len, args.batch_size,
                          args.control_weight, random.Random(seed + 7777))
        return all_ep, vb

    kind_table = torch.tensor(vocab.kind_table, dtype=torch.long, device=device)
    torch.manual_seed(args.seed)
    if device.type == "cuda":
        torch.cuda.manual_seed_all(args.seed)
    random.seed(args.seed)

    # 启动自检：一个真实的前向+反向，AMP API 有问题时立刻报清楚
    probe_batch = make_batches(c_seqs["train"][:2], vocab, min(32, args.seq_len), 2,
                               args.control_weight, random.Random(0), limit=1)[0]
    tmp = PrismModel(vocab.vocab_size, PRESETS[args.preset], seed=args.seed).net.to(device)
    with autocast():
        x, y, w = to_device(probe_batch, torch, device, vocab)
        _, l, _ = tmp(x, y, w)
    l.backward()
    del tmp, x, y, w, l
    if device.type == "cuda":
        torch.cuda.empty_cache()
    print(f"[self-test] 前向/反向 OK（dtype={dtype}）")

    metrics: Dict[str, Any] = {"dtype": dtype, "coverage": coverage}

    def run_group(tag: str, seqs, seed: int):
        model = PrismModel(vocab.vocab_size, PRESETS[args.preset], seed=seed)
        model.net.to(device)
        ep_batches, val_batches = batches_for(seqs, seed)
        summary = train_group(model, ep_batches, val_batches, vocab, device, cfg,
                              autocast, scaler, torch, tag, out_dir, kind_table)
        best = out_dir / "checkpoints" / f"{tag}_best.pt"
        if best.exists():
            try:
                blob = torch.load(best, map_location=device, weights_only=False)
            except TypeError:  # torch < 2.0 不认 weights_only
                blob = torch.load(best, map_location=device)
            model.net.load_state_dict(blob["model"])
        return model, summary

    def eval_generation(model: PrismModel, tag: str, expect_validation: bool) -> Dict[str, Any]:
        subset = splits["test"][:args.eval_gen_samples]
        free, cons, samples_out = [], [], []
        for row in subset:
            # v3.2：scattered 的窗口必须在推理 prompt 里复现，否则训练/推理
            # 分布不一致（实测把 ③ 从 0.9808 打到 0.4808）。
            extra = (row.get("_scatter_window") or []) \
                if args.decision_position == "scattered" else None
            f = generate(model, vocab, row, device, torch, autocast,
                         args.max_new_tokens, False, expect_validation,
                         prompt_extra=extra)
            c = generate(model, vocab, row, device, torch, autocast,
                         args.max_new_tokens, True, expect_validation,
                         prompt_extra=extra)
            free.append(f)
            cons.append(c)
            # 归因要能分「截断」与「真非法」：原 samples_out 只写 structure_ok，
            # 没有 truncated / n_tokens，事后无法区分这两种失败，这里补齐。
            samples_out.append({"tag": tag, "category": row["_category"],
                                "task": row["task"], "free_code": f["code_text"][:400],
                                "answer": f["answer_text"][:400],
                                "free_structure_ok": f["structure_ok"],
                                "free_problems": f["structure_problems"],
                                "free_truncated": f["truncated"],
                                "free_n_tokens": f["n_tokens"],
                                "free_n_decision": f["n_decision"],
                                "free_tokens_per_s": f["tokens_per_s"],
                                "constrained_structure_ok": c["structure_ok"],
                                "constrained_problems": c["structure_problems"],
                                "constrained_truncated": c["truncated"],
                                "json_exact": f["json_exact"]})
        counted = [r for r in free if not r["truncated"]]
        jt = [r for r in free if r["is_json_task"]]
        n_valid = sum(1 for r in jt if r["json_valid"])
        n_exact = sum(1 for r in jt if r["json_exact"])
        tps = sum(r["tokens_per_s"] for r in free) / max(len(free), 1)
        dec_density = (sum(r["n_decision"] for r in free) /
                       max(sum(r["n_tokens"] for r in free), 1))
        # v3：判据 ③ 用**全分母**。截断生成必然没吐出 </CODE>/<V:...>，
        # check_structure 必判非法，是一次失败输出，不许从分母里剔除。
        n_all = len(free)
        n_struct_ok_all = sum(1 for r in free if r["structure_ok"] and not r["truncated"])
        return {
            "free": {
                "structure_rate": round(sum(1 for r in counted if r["structure_ok"]) /
                                        len(counted), 4) if counted else None,
                "structure_rate_all": round(n_struct_ok_all / n_all, 4) if n_all else None,
                "n_all": n_all,
                "n_counted": len(counted), "n_truncated": len(free) - len(counted),
                "n_struct_ok_all": n_struct_ok_all,
                "tokens_per_s": round(tps, 1),
            },
            "constrained": {
                "structure_rate": round(sum(1 for r in cons if r["structure_ok"] and not r["truncated"]) /
                                        max(sum(1 for r in cons if not r["truncated"]), 1), 4),
                "note": "外部状态机强制，不计入判据 ③，仅对照",
            },
            "json": {"n": len(jt), "valid": n_valid, "exact": n_exact,
                     "valid_rate": round(n_valid / max(len(jt), 1), 4),
                     "exact_rate": round(n_exact / max(len(jt), 1), 4),
                     "non_json_tasks_unknown": len(free) - len(jt)},
            "decision_density": round(dec_density, 6),
            "samples": samples_out,
        }

    print("\n===== C 组：统一序列（本方案） =====")
    c_model, c_train = run_group("C", c_seqs, args.seed)
    metrics["C"] = {"train": {k: v for k, v in c_train.items() if k != "history"},
                    "probe": train_probe(c_model, vocab, splits, c_seqs, device, torch,
                                         autocast, args.probe_epochs, args.seed),
                    "gen": eval_generation(c_model, "C", True)}
    metrics["params"] = c_model.net.n_params()
    print("C 探针:", json.dumps(metrics["C"]["probe"], ensure_ascii=False))

    # v3 P2：阶段一几何检查点（§7）+ 梯度范数摘要（§8.6）
    metrics["embedding_geometry"] = embedding_geometry(
        c_model, vocab, c_seqs["train"], torch)
    metrics["grad_norm_summary"] = grad_norm_summary(c_train.get("history", []))
    print("几何检查点:", json.dumps(metrics["embedding_geometry"], ensure_ascii=False))

    print("\n===== A 组：外挂轻量决策分类器 =====")
    metrics["A"] = train_decision_baseline(vocab, splits, c_seqs, device, torch,
                                           args.baseline_epochs, args.seed)
    print("A:", json.dumps(metrics["A"], ensure_ascii=False))

    if args.a_group_rival:
        print("\n===== A' 组：冻结主干 + 同 pos-1 特征 + MLP（对等对照） =====")
        metrics["A_rival"] = train_probe_rival(
            c_model, vocab, splits, c_seqs, device, torch, autocast,
            args.probe_epochs, args.seed)
        print("A':", json.dumps(metrics["A_rival"], ensure_ascii=False))

    if cfg["b_group"]:
        print("\n===== B 组：去掉决策/验证 token 的纯生成 =====")
        b_model, b_train = run_group("B", b_seqs, args.seed + 101)
        b_gen = eval_generation(b_model, "B", False)
        metrics["B"] = {"train": {k: v for k, v in b_train.items() if k != "history"},
                        "gen": b_gen}
        c_tps, b_tps = metrics["C"]["gen"]["free"]["tokens_per_s"], b_gen["free"]["tokens_per_s"]
        metrics["C"]["gen"]["speed_drop_vs_B"] = round(max(0.0, (b_tps - c_tps) / max(b_tps, 1e-6)), 4)
    else:
        metrics["C"]["gen"]["speed_drop_vs_B"] = None

    if cfg["shuffle_control"]:
        print("\n===== 负对照：决策标签同点内打乱 =====")
        s_model, s_train = run_group("shuffle", shuf_seqs, args.seed + 202)
        metrics["shuffle"] = {"train": {k: v for k, v in s_train.items() if k != "history"},
                              "probe": train_probe(s_model, vocab, splits, shuf_seqs, device,
                                                   torch, autocast, args.probe_epochs, args.seed),
                              "gen": {"free": {}, "constrained": {}, "json": {}}}

    verdict = judge(metrics, cfg)
    metrics["verdict"] = verdict
    (out_dir / "metrics.json").write_text(
        json.dumps(metrics, ensure_ascii=False, indent=2, default=str), encoding="utf-8")
    with (out_dir / "generated_samples.jsonl").open("w", encoding="utf-8") as fh:
        for tag in ("C", "B", "shuffle"):
            if tag in metrics and metrics[tag].get("gen", {}).get("samples"):
                for s in metrics[tag]["gen"]["samples"]:
                    fh.write(json.dumps(s, ensure_ascii=False) + "\n")
    report_md = render_report(metrics, cfg, env, st, verdict)
    (out_dir / "report.md").write_text(report_md, encoding="utf-8")

    # v3 P3：docs/探针实验设计.md §8 产出物——把报告与原始指标落进 reports/
    if not args.no_report_to_repo:
        try:
            repo_reports = Path(__file__).resolve().parent / "reports"
            repo_reports.mkdir(parents=True, exist_ok=True)
            stamp = time.strftime("%Y-%m-%d")
            (repo_reports / f"探针实验_{stamp}.md").write_text(report_md, encoding="utf-8")
            (repo_reports / f"探针实验_{stamp}.json").write_text(
                json.dumps(metrics, ensure_ascii=False, indent=2, default=str),
                encoding="utf-8")
            print(f"[report] §8 产出物已写入 {repo_reports}/探针实验_{stamp}.{{md,json}}")
        except OSError as exc:
            print(f"[report] 仓库 reports/ 不可写，跳过 §8 产出物：{exc}")

    print("\n===== 结论 =====")
    print(json.dumps(verdict, ensure_ascii=False, indent=2))
    print(f"\n全部产物：{out_dir.resolve()}")
    if args.c2net_upload and c2net_upload:
        c2net_upload()
        print("[openi] upload_output() 已调用")
    return 0 if verdict["verdict"] != "invalid" else 2


if __name__ == "__main__":
    raise SystemExit(main())
